window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc03"]={"id":"bc03","title":"3. 蛋白质的三维结构","sub":"朱圣庚《生物化学》第4版 · 第3章","sub2":"第3章 · 41页老师PPT + 10页AI串讲 + 6页AI图解 + 5页公式精讲 + 1页反应式 + 6页原书页 + 5页原书单图 + 4页过程 + 评估","modules":[{"i":0,"name":"第3章 蛋白质的三维结构（老师PPT精讲+AI补充+习题精解）","slides":[{"sec":"第3章 · 概述","title":"第3章 蛋白质的三维结构","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。本章讲蛋白质三维结构：弱作用力、测定方法、二级结构、纤维蛋白、结构域、球状三级、膜蛋白、四级结构、变性与折叠。对应原书第3章。","img":"assets/img/bc02/full108.jpg","points":["第3章 蛋白质的三维结构","对应老师第5章","七节：概述/方法/二级/纤维/结构域/球状三级/膜蛋白"],"i":0,"check":{"kind":"short","id":"bc03_c0_check","q":"第3章主要研究哪些内容？","a":"蛋白质三维结构概述、测定方法、二级结构、纤维状蛋白、超二级/结构域、球状三级、膜蛋白、四级结构、变性与折叠。","e":"九节主线。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：本章讲蛋白质三维结构：弱作用力、测定方法、二级结构、纤维蛋白、结构域、球状三级、膜蛋白、四级结构、变性与折叠。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：第3章 蛋白质的三维结构；对应老师第5章。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲1：三维结构概述","notes":"【图源】AI串讲配图/原书图。三维结构由弱相互作用稳定；肽键平面刚性；主链折叠受φ/ψ限制。","points":["弱作用力：氢键、疏水作用、范德华力、离子键；单个弱，集体稳定。","肽键C—N有部分双键性质，六原子共平面；φ/ψ可旋转。","Ramachandran图：允许区/禁区；Gly、Pro特殊。","三级结构=一条链三维折叠；四级=亚基组装。"],"check":{"kind":"short","id":"bc03_ai1_check","q":"稳定蛋白质三维结构的主要作用力有哪些？","a":"氢键、疏水作用、范德华力、离子键；疏水作用常是主要驱动力。","e":"记“弱作用力集体稳定”。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai1_exam","q":"球蛋白折叠的主要驱动力通常是？","o":["A. 疏水作用","B. 肽键","C. 二硫键","D. 磷酸二酯键"],"a":"A","e":"疏水残基埋入内部，减少水化熵损失。","src":"AI补充·选择"},"i":1,"img":"assets/img/bc03ai/fourlevel.svg","imageExplain":"这张总览图把一级→二级→三级→四级串起来：先看氨基酸序列，再看α/β元件，再看一条链的三维折叠，最后看多亚基组装。"},{"sec":"第3章 · 一、三维结构概述","title":"稳定三维结构的作用力：总览","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。稳定三维结构主要靠非共价次级键：氢键、疏水作用、范德华力、离子键；二硫键为共价交联。疏水作用通常是三级结构主要驱动力。","img":"assets/img/bc02/full115.jpg","points":["二、稳定蛋白质三维结构的作用力"],"i":2,"exam":{"kind":"mcq","id":"bc03_q19","q":"稳定三级结构的主要作用力通常是？","o":["A. 疏水作用","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"疏水作用是三级结构主要驱动力。","src":"页级选择题"},"imageExplain":"这张图主要在讲：稳定三维结构主要靠非共价次级键：氢键、疏水作用、范德华力、离子键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：二、稳定蛋白质三维结构的作用力。"},{"sec":"第3章 · 一、三维结构概述","title":"疏水作用（熵效应）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。疏水残基在水环境中趋向内部，减少水化熵损失；这是球状蛋白折叠的主要驱动力。疏水核心使蛋白稳定，亲水残基朝外。","img":"assets/img/bc02/full116.jpg","points":["（三）疏水作用( 熵效应) （四）盐键 （五）二硫键 （一）氢键 （二）范德华力 定向效应 诱导效应 分散效应"],"i":3,"check":{"kind":"short","id":"bc03_c3_check","q":"疏水作用为什么是球状蛋白折叠的主要驱动力？","a":"疏水残基埋入内部，减少水化熵损失；疏水核心稳定三级结构。","e":"熵驱动。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q1","q":"疏水作用的主要驱动力是？","o":["A. 减少水化熵损失","B. 形成肽键","C. 形成二硫键","D. 增加电荷"],"a":"A","e":"疏水残基埋入内部，减少水化熵损失。","src":"页级选择题"},"imageExplain":"这张图主要在讲：疏水残基在水环境中趋向内部，减少水化熵损失。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：（三）疏水作用( 熵效应) （四）盐键 （五）二硫键 （一）氢键 （二）范德华力 定向效应 诱导效应 分散效应。"},{"sec":"第3章 · 一、三维结构概述","title":"多肽主链的折叠","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。肽键具有部分双键性质，六原子共平面；主链只能绕φ/ψ旋转，空间位阻限制可允许构象。","img":"assets/img/bc02/full117.jpg","points":["三、多肽主链折 叠的空间限制 （一）酰胺平面与 α- 碳原子的二面角 （φ 和ψ ）： 规定键两侧基 团为顺式排列时为 0o ，从C 沿键轴方 向观察，顺时针旋 转的角度为正值"],"i":4,"check":{"kind":"short","id":"bc03_c4_check","q":"肽键为什么不能自由旋转？","a":"肽键C—N具有部分双键性质，六原子共平面；主链只绕φ/ψ旋转。","e":"部分双键。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q2","q":"肽键C—N不能自由旋转的主要原因是？","o":["A. 部分双键性质","B. 肽键太长","C. 侧链太大","D. 氢键太弱"],"a":"A","e":"肽键有部分双键性质，六原子共平面。","src":"页级选择题"},"imageExplain":"这张图主要在讲：肽键具有部分双键性质，六原子共平面。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：三、多肽主链折 叠的空间限制 （一）酰胺平面与 α- 碳原子的二面角 （φ 和ψ ）： 规定键两侧基 团为顺式排列时为 0o ，从C 沿键轴方 向观察，顺时针旋 转的角度为正值。"},{"sec":"第3章 · 一、三维结构概述","title":"Ramachandran图：可允许的φ/ψ","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。Ramachandran图以φ/ψ为坐标，显示允许/不允许区；α螺旋、β折叠落在允许区，Gly/Pro特殊。","img":"assets/img/bc02/full118.jpg","points":["（二）可允许的φ 和ψ ：拉氏构象图"],"i":5,"check":{"kind":"short","id":"bc03_c5_check","q":"Ramachandran图以哪两个二面角为坐标？","a":"φ（N—Cα）和ψ（Cα—C）。","e":"φ/ψ。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q3","q":"Ramachandran图的坐标是？","o":["A. φ和ψ","B. pH和pI","C. 分子量和电荷","D. λ和θ"],"a":"A","e":"以主链二面角φ/ψ为坐标。","src":"页级选择题"},"imageExplain":"这张图主要在讲：Ramachandran图以φ/ψ为坐标，显示允许/不允许区。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：（二）可允许的φ 和ψ ：拉氏构象图。"},{"sec":"第3章 · 一、三维结构概述","title":"Ramachandran图：允许区与禁区","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。允许区对应无位阻构象；不允许区因原子碰撞被禁。多数残基落在α/β区，Gly有更大允许范围。","img":"assets/img/bc02/full119.jpg","points":["( 二) 可允许 的φ 和ψ 值：拉氏构 象图 由印度学者 Ramachandran 制 作"],"i":6,"check":{"kind":"short","id":"bc03_c6_check","q":"Ramachandran图的允许区和禁区由什么决定？","a":"主链原子间的空间位阻；允许区无碰撞、能量低，不允许区有碰撞。","e":"空间位阻。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：允许区对应无位阻构象。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二) 可允许 的φ 和ψ 值：拉氏构 象图 由印度学者 Ramachandran 制 作。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲2：结构测定方法","notes":"【图源】AI串讲配图/原书图。X射线看晶体、NMR看溶液、CD看二级结构、冷冻电镜看大复合物；按样品状态和分辨率选方法。","points":["X射线：晶体、高分辨率、Bragg方程；难长晶体。","NMR：溶液、动态、小到中等蛋白。","CD：快速判断二级结构，低分辨率。","冷冻电镜：大复合物/膜蛋白，近原子分辨率。"],"table":[["方法","样品","优点","局限"],["X射线","晶体","高分辨率","需晶体"],["NMR","溶液","动态/小蛋白","大小限制"],["CD","溶液","快速","低分辨率"],["冷冻电镜","大复合物","近原子","设备/数据处理"]],"tableTitle":"结构测定方法比较","check":{"kind":"short","id":"bc03_ai2_check","q":"X射线、NMR、CD各适合什么样品/信息？","a":"X射线适合晶体高分辨率结构；NMR适合溶液动态中小蛋白；CD快速判断二级结构。","e":"按样品状态和分辨率选。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai2_exam","q":"研究溶液中蛋白质二级结构最常用的快速方法是？","o":["A. CD","B. X射线衍射","C. 冷冻电镜","D. 超速离心"],"a":"A","e":"圆二色性可快速判断α螺旋/β折叠含量。","src":"AI补充·选择"},"i":7,"img":"assets/img/bc02/full110.jpg","imageExplain":"这张图以X射线衍射为例：X射线打到晶体上产生衍射，再由衍射点反推电子密度和原子位置；NMR/CD/电镜则分别适合溶液、二级结构和大复合物。"},{"sec":"第3章 · 二、结构测定方法","title":"研究蛋白质构象的方法：总览","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。研究构象方法：X射线（晶体）、NMR（溶液/动态）、CD（二级结构）、冷冻电镜（大复合物/膜蛋白）、荧光/超速离心等。","img":"assets/img/bc02/full109.jpg","points":["一、研究蛋白质构象的方法 ( 一)X 射线衍射法"],"i":8,"exam":{"kind":"mcq","id":"bc03_q20","q":"研究蛋白质晶体结构最常用的方法是？","o":["A. X射线衍射","B. CD","C. NMR","D. 超速离心"],"a":"A","e":"X射线衍射解析晶体结构。","src":"页级选择题"},"imageExplain":"这张图主要在讲：研究构象方法：X射线（晶体）、NMR（溶液/动态）、CD（二级结构）、冷冻电镜（大复合物/膜蛋白）、荧光/超速离心等。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：一、研究蛋白质构象的方法 ( 一)X 射线衍射法。"},{"sec":"第3章 · 二、结构测定方法","title":"X射线衍射与Bragg方程","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。X射线衍射用晶体，Bragg方程2d sinθ=nλ；衍射点→电子密度→建模。需解决相位问题。","img":"assets/img/bc02/full110.jpg","points":["基本规律：X 射线穿过原子平面层时，当光程差等于波长的倍 数，反射波可以互相叠加形成衍射斑点","如图5-2 所示，光程 差等于2dsinθ, 上述规律可总结为Bragg 方程： 2dsinθ=nλ(n=±1, ±2, ±3…)"],"check":{"kind":"short","id":"bc03_c9_check","q":"Bragg方程是什么？d代表什么？","a":"2d sinθ=nλ；d为晶面间距，θ为掠射角。","e":"X射线衍射。","src":"老师PPT·针对性自测"},"i":9,"exam":{"kind":"mcq","id":"bc03_q4","q":"X射线衍射解析蛋白质结构通常需要？","o":["A. 晶体","B. 溶液","C. 膜","D. 活细胞"],"a":"A","e":"X射线衍射需要蛋白质晶体。","src":"页级选择题"},"imageExplain":"这张图在讲“X射线怎样读出晶体里的原子排列”。把X射线看成波：打到晶体中一层层原子上，相邻层反射的波发生干涉；当光程差正好是波长的整数倍时，就出现衍射斑点。图中关键是入射角θ、晶面间距d和Bragg方程2d sinθ=nλ：d越小、θ越大。记住“晶体→衍射→电子密度→结构模型”这条线。"},{"sec":"第3章 · 二、结构测定方法","title":"溶液中蛋白质构象的光谱方法","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。溶液构象方法：CD、荧光、NMR、超速离心等；CD快速判断二级结构，NMR给原子级信息。","img":"assets/img/bc02/full111.jpg","points":["( 二) 研究溶液中蛋白质构象的光谱学方法 1. 紫外差光谱 芳香族氨 基酸在极性环境下 吸收峰向短波长移 动，称作篮移，反 之会红移","2. 荧光和荧光偏振 变性和非 变性蛋白质荧光峰 和荧光偏振的位置 会有特定的变化"],"check":{"kind":"short","id":"bc03_c10_check","q":"CD和NMR分别能提供什么信息？","a":"CD快速判断二级结构；NMR提供溶液中原子的化学位移/NOE等结构约束。","e":"CD二级，NMR原子级。","src":"老师PPT·针对性自测"},"i":10,"exam":{"kind":"mcq","id":"bc03_q21","q":"下列哪项可在溶液中研究构象？","o":["A. CD/NMR","B. 只X射线","C. 只电镜","D. 只测序"],"a":"A","e":"CD/NMR可在溶液中研究构象。","src":"页级选择题"},"imageExplain":"这张图主要在讲：溶液构象方法：CD、荧光、NMR、超速离心等。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二) 研究溶液中蛋白质构象的光谱学方法 1. 紫外差光谱 芳香族氨 基酸在极性环境下 吸收峰向短波长移 动，称作篮移，反 之会红移；2. 荧光和荧光偏振 变性和非 变性蛋白质荧光峰 和荧光偏振的位置 会有特定的变化。"},{"sec":"第3章 · 二、结构测定方法","title":"圆二色性（CD）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。CD是左/右旋圆偏振光吸收差；远紫外反映主链二级结构，近紫外反映芳香族/三级环境。","img":"assets/img/bc02/full112.jpg","points":["3. 圆二色性 由尼科尔棱镜产生 由电光调制器产生"],"i":11,"check":{"kind":"short","id":"bc03_c11_check","q":"CD远紫外区主要反映什么？","a":"主链二级结构（α螺旋、β折叠、无规卷曲）。","e":"远紫外=二级结构。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q5","q":"CD最常用于快速判断？","o":["A. 二级结构","B. 四级结构","C. 二硫键位置","D. 膜蛋白拓扑"],"a":"A","e":"CD可快速判断α螺旋/β折叠含量。","src":"页级选择题"},"imageExplain":"这张图在讲“CD怎样看蛋白质二级结构”。CD用左旋和右旋圆偏振光照射样品，手性结构对两种光的吸收不一样，差值就是CD信号。远紫外区（约190–250 nm）主要反映主链构象：α螺旋有特征双负峰，β折叠和无规卷曲的谱形不同。看图时先认“左/右旋光→吸收差→谱形→二级结构”。"},{"sec":"第3章 · 二、结构测定方法","title":"圆二色性的原理","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。CD原理：手性环境使左右旋光吸收不同；α螺旋有特征双负峰，β折叠/无规卷曲谱形不同。","img":"assets/img/bc02/full113.jpg","points":["圆偏振光可看成是相位相差90o 的两个 平面偏振光叠加而成，若左、右圆偏振 光因被测物的吸收而振幅不同，二者叠 加会形成椭圆偏振光","椭圆率θ= 短轴/ 长轴 =tanθ ≈33cl∆ε( 适合于小的θ ， ∆ε= εR− εL ，c 为摩尔浓度，l 为光程，ε 为摩尔吸光系数） 摩尔椭圆率[θ]λ=θ/cl×100=3300 ∆ε"],"check":{"kind":"short","id":"bc03_c12_check","q":"CD为什么能区分不同二级结构？","a":"手性环境使左/右旋圆偏振光吸收不同；不同二级结构有特征CD谱。","e":"左右旋吸收差。","src":"老师PPT·针对性自测"},"i":12,"imageExplain":"这张图在解释CD为什么能区分构象：圆偏振光可看成两个相位差90°的振动分量；样品是手性环境时，左右旋光被吸收的程度不同，产生椭圆率和吸收差。不同二级结构的主链排列不同，所以CD谱形不同。看图抓住“手性→左右旋吸收不等→有特征谱”。"},{"sec":"第3章 · 二、结构测定方法","title":"核磁共振（NMR）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。NMR在溶液中测结构/动态；需同位素标记，利用化学位移、NOE等约束；适合小到中等蛋白。","img":"assets/img/bc02/full114.jpg","points":["4. 核磁共振(NMR)"],"i":13,"check":{"kind":"short","id":"bc03_c13_check","q":"NMR适合研究什么状态的蛋白质？","a":"溶液状态、小到中等蛋白的结构和动态；常需同位素标记。","e":"溶液/动态。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q6","q":"NMR最适合研究？","o":["A. 溶液中小到中等蛋白","B. 只适合晶体","C. 只适合大复合物","D. 只适合核酸"],"a":"A","e":"NMR研究溶液中蛋白质结构和动态。","src":"页级选择题"},"imageExplain":"这张图在讲“NMR怎样在溶液里测蛋白质”。把蛋白放在强磁场中，某些原子核（如¹H、¹³C、¹⁵N）吸收特定频率的射频，产生共振峰；不同化学环境→不同化学位移，相邻核还会让峰分裂；NOE能给出空间上靠近的原子对。把这些距离/角度约束交给计算，就能得到溶液中的三维结构。看图先认“峰位置=环境、峰分裂=邻居、NOE=空间距离”。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲3：二级结构","notes":"【图源】AI串讲配图/原书图。α螺旋、β折叠、β转角、无规卷曲；氢键模式决定结构。","points":["α螺旋：3.6残基/圈，螺距0.54 nm，i→i+4氢键。","β折叠：平行/反平行，链间氢键，轴心距0.35 nm。","β转角：4个残基，Gly/Pro常见；无规卷曲也有确定构象。","二级结构由主链氢键稳定，侧链决定稳定性/取向。"],"check":{"kind":"short","id":"bc03_ai3_check","q":"α螺旋和β折叠的氢键模式有何不同？","a":"α螺旋是主链i→i+4氢键；β折叠是链间氢键，平行或反平行。","e":"记氢键模式。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai3_exam","q":"α螺旋中每个残基的—NH与哪个残基的—CO形成氢键？","o":["A. 后第4个","B. 前第4个","C. 相邻","D. 侧链"],"a":"A","e":"α螺旋为i→i+4主链氢键。","src":"AI补充·选择"},"i":14,"img":"assets/img/bc03ai/secondary.svg","imageExplain":"这张图把四种二级结构放在一起：α螺旋看i→i+4氢键和3.6残基/圈；β折叠看链间氢键和0.35 nm轴心距；β转角让链回折；无规卷曲没有规则重复但仍有确定构象。"},{"sec":"第3章 · 三、二级结构","title":"二级结构：α螺旋","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋：3.6残基/圈，螺距0.54 nm，i→i+4主链氢键；右手螺旋，侧链朝外。","img":"assets/img/bc02/full120.jpg","points":["四、二级结构：多肽链折叠的规则方式 ( 一)α 螺旋 1.α 螺旋的结构 多肽链中的各个肽平面围绕同一轴旋转，形成 螺旋结构，螺旋一周，沿轴上升的距离即螺距为 0.54nm, 含3.6 个氨基酸残基","两个氨基酸之间的 距离为0.15nm","肽链内形成氢键，氢键的取向几乎与轴平行， 每一个氨基酸残基的酰胺基团的-NH 基与其后第四 个氨基酸残基酰胺基团的-CO 基形成氢键"],"check":{"kind":"short","id":"bc03_c15_check","q":"α螺旋的氢键模式和结构参数是什么？","a":"i→i+4主链氢键；3.6残基/圈，螺距0.54 nm，右手螺旋。","e":"3.6/0.54/i→i+4。","src":"老师PPT·针对性自测"},"i":15,"exam":{"kind":"mcq","id":"bc03_q7","q":"α螺旋的氢键模式是？","o":["A. i→i+4","B. i→i+1","C. 链间","D. 侧链间"],"a":"A","e":"α螺旋为主链i→i+4氢键。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α螺旋：3.6残基/圈，螺距0.54 nm，i→i+4主链氢键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：四、二级结构：多肽链折叠的规则方式 ( 一)α 螺旋 1.α 螺旋的结构 多肽链中的各个肽平面围绕同一轴旋转，形成 螺旋结构，螺旋一周，沿轴上升的距离即螺距为 0.54nm, 含3.6 个氨基酸残基；两个氨基酸之间的 距离为0.15nm。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋的结构参数","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋每残基沿轴上升0.15 nm、旋转约100°；n残基长度≈(n/3.6)×0.54 nm。","img":"assets/img/bc02/full121.jpg","points":["每残基上升0.15 nm、旋转约100°。","n残基长度≈(n/3.6)×0.54 nm。","3.6残基/圈，螺距0.54 nm。"],"i":16,"exam":{"kind":"mcq","id":"bc03_q8","q":"α螺旋每圈约含多少个残基？","o":["A. 3.6","B. 2.0","C. 4.0","D. 10"],"a":"A","e":"α螺旋3.6残基/圈，螺距0.54 nm。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α螺旋每残基沿轴上升0.15 nm、旋转约100°。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：每残基上升0.15 nm、旋转约100°。；n残基长度≈(n/3.6)×0.54 nm。。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋结构图","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋结构图：主链绕中心轴盘绕，氢键平行轴，侧链向外；注意右手性和每圈3.6残基。","img":"assets/img/bc02/full122.jpg","points":["* * 3.613 螺旋"],"i":17,"check":{"kind":"short","id":"bc03_c17_check","q":"α螺旋图中侧链朝哪、氢键方向如何？","a":"侧链朝外；氢键几乎平行于螺旋轴，连接i与i+4。","e":"侧链外、氢键平行轴。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：α螺旋结构图：主链绕中心轴盘绕，氢键平行轴，侧链向外。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：* * 3.613 螺旋。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋的偶极矩和帽化","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋有宏观偶极矩，N端部分正、C端部分负；N端常由带负电残基/帽化稳定。","img":"assets/img/bc02/full123.jpg","points":["2.α 螺旋的偶 极矩和帽化"],"i":18,"check":{"kind":"short","id":"bc03_c18_check","q":"α螺旋的偶极矩方向及帽化作用？","a":"N端部分正、C端部分负；N端帽化/负电荷残基稳定螺旋。","e":"偶极+帽化。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：α螺旋有宏观偶极矩，N端部分正、C端部分负。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：2.α 螺旋的偶 极矩和帽化。"},{"sec":"第3章 · 三、二级结构","title":"α螺旋的稳定性","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α螺旋稳定性受氢键、侧链相互作用、螺旋倾向、电荷和Pro/Gly影响；连续Pro中断螺旋。","img":"assets/img/bc02/full124.jpg","points":["3.α 螺旋 的手性"],"i":19,"check":{"kind":"short","id":"bc03_c19_check","q":"哪些因素会降低α螺旋稳定性？","a":"连续Pro/Gly、同种电荷排斥、空间位阻、不利侧链相互作用。","e":"Pro/Gly/电荷。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q23","q":"下列哪种因素不利于α螺旋？","o":["A. 连续Pro","B. 连续Ala","C. 连续Leu","D. 适宜pH"],"a":"A","e":"Pro中断α螺旋。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α螺旋稳定性受氢键、侧链相互作用、螺旋倾向、电荷和Pro/Gly影响。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：3.α 螺旋 的手性。"},{"sec":"第3章 · 三、二级结构","title":"影响α螺旋形成的因素","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。影响α螺旋：Ala/Leu/Glu等倾向高；Pro/Gly破坏；同种电荷/空间位阻不利；环境pH影响带电残基。","img":"assets/img/bc02/full125.jpg","points":["4. 影响α 螺旋形成的因素：R 基太小使键角自由度过大，带同种电荷 的R 基相互靠近，β 碳原子上有分支均不利于形成α 螺旋，含脯氨酸的 肽段不能形成α 螺旋"],"i":20,"check":{"kind":"short","id":"bc03_c20_check","q":"Pro和Gly对α螺旋分别有什么影响？","a":"Pro环状结构中断螺旋；Gly柔性大，降低螺旋倾向。","e":"Pro中断，Gly柔性。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q9","q":"最常中断α螺旋的残基是？","o":["A. Pro","B. Ala","C. Leu","D. Glu"],"a":"A","e":"Pro环状结构使主链弯折，中断螺旋。","src":"页级选择题"},"imageExplain":"这张图主要在讲：影响α螺旋：Ala/Leu/Glu等倾向高。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：4. 影响α 螺旋形成的因素：R 基太小使键角自由度过大，带同种电荷 的R 基相互靠近，β 碳原子上有分支均不利于形成α 螺旋，含脯氨酸的 肽段不能形成α 螺旋。"},{"sec":"第3章 · 三、二级结构","title":"其他类型的螺旋","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。其他螺旋：3₁₀螺旋（3残基/圈）、π螺旋（4.4残基/圈）、左手α螺旋；常见但少于α螺旋。","img":"assets/img/bc02/full126.jpg","points":["5 . 其他类型的螺旋 4.416 螺旋"],"i":21,"check":{"kind":"short","id":"bc03_c21_check","q":"3₁₀螺旋和π螺旋每圈约多少残基？","a":"3₁₀约3残基/圈；π螺旋约4.4残基/圈。","e":"3与4.4。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q22","q":"下列哪种不是常见二级结构？","o":["A. 3₁₀螺旋","B. α螺旋","C. β折叠","D. 肽键"],"a":"A","e":"肽键是化学键，不是二级结构。","src":"页级选择题"},"imageExplain":"这张图主要在讲：其他螺旋：3₁₀螺旋（3残基/圈）、π螺旋（4.4残基/圈）、左手α螺旋。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：5 . 其他类型的螺旋 4.416 螺旋。"},{"sec":"第3章 · 三、二级结构","title":"β折叠片","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β折叠：肽链伸展、链间氢键；相邻残基轴心距0.35 nm；侧链交替位于片层两侧。","img":"assets/img/bc02/full127.jpg","points":["( 二)β 折叠片 - 折叠是由两条或多条几乎完全伸展的肽链平行排列， 通过链间的氢键交联而形成的","肽链的主链呈锯齿桩折叠构 象","两个氨基酸之间的轴心距为0.35nm"],"check":{"kind":"short","id":"bc03_c22_check","q":"β折叠的链间氢键方向和轴心距？","a":"链间氢键与链长轴接近垂直；相邻残基轴心距约0.35 nm。","e":"垂直/0.35 nm。","src":"老师PPT·针对性自测"},"i":22,"exam":{"kind":"mcq","id":"bc03_q10","q":"β折叠的链间氢键方向通常？","o":["A. 与链长轴接近垂直","B. 与链长轴平行","C. 与侧链平行","D. 无方向"],"a":"A","e":"β折叠链间氢键与链长轴接近垂直。","src":"页级选择题"},"imageExplain":"这张图主要在讲：β折叠：肽链伸展、链间氢键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二)β 折叠片 - 折叠是由两条或多条几乎完全伸展的肽链平行排列， 通过链间的氢键交联而形成的；肽链的主链呈锯齿桩折叠构 象。"},{"sec":"第3章 · 三、二级结构","title":"平行与反平行β折叠","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。平行β折叠链方向相同，反平行方向相反；反平行氢键更规则，常见于球状蛋白。","img":"assets/img/bc02/full128.jpg","points":["- 折叠有两 种类型","一种 为平行式，即 所有肽链的 N- 端都在同 一边","另一种 为反平行式， 即相邻两条肽 链的方向相反"],"check":{"kind":"short","id":"bc03_c23_check","q":"平行与反平行β折叠的主要区别？","a":"平行链方向相同，反平行方向相反；反平行氢键更规则。","e":"方向/氢键。","src":"老师PPT·针对性自测"},"i":23,"exam":{"kind":"mcq","id":"bc03_q11","q":"平行β折叠的特点是？","o":["A. 链方向相同","B. 链方向相反","C. 无氢键","D. 只含α螺旋"],"a":"A","e":"平行β折叠链方向相同；反平行相反。","src":"页级选择题"},"imageExplain":"这张图主要在讲：平行β折叠链方向相同，反平行方向相反。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：- 折叠有两 种类型；一种 为平行式，即 所有肽链的 N- 端都在同 一边。"},{"sec":"第3章 · 三、二级结构","title":"β折叠结构图（一）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β折叠结构图一：锯齿状主链、链间氢键、侧链上下交替；注意与α螺旋的氢键方向不同。","img":"assets/img/bc02/full129.jpg","points":["β折叠链间氢键与链轴接近垂直。","相邻残基轴心距0.35 nm。","侧链交替位于片层两侧。"],"i":24,"imageExplain":"这张图主要在讲：β折叠结构图一：锯齿状主链、链间氢键、侧链上下交替。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：β折叠链间氢键与链轴接近垂直。；相邻残基轴心距0.35 nm。。"},{"sec":"第3章 · 三、二级结构","title":"β折叠结构图（二）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β折叠结构图二：平行/反平行排列与扭曲；β片层可形成β桶/β螺旋等超二级结构。","img":"assets/img/bc02/full130.jpg","points":["平行/反平行β折叠。","β片层可扭曲/形成β桶。","侧链交替。"],"i":25,"imageExplain":"这张图主要在讲：β折叠结构图二：平行/反平行排列与扭曲。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：平行/反平行β折叠。；β片层可扭曲/形成β桶。。"},{"sec":"第3章 · 三、二级结构","title":"β转角和β凸起","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。β转角由4个残基组成，第一个C=O与第四个N—H形成氢键；Gly/Pro常见，使链回折。β凸起是局部不规则。","img":"assets/img/bc02/full131.jpg","points":["( 三)β 转角和β 凸 起 - 转角由四个氨基酸残基组成，弯曲处的第一个氨基酸 残基的 -C=O 和第四个残基的– N-H 之间形成氢键，形 成一个不很稳定的环状结构","这类结构主要存在于球状蛋白分子中"],"check":{"kind":"short","id":"bc03_c26_check","q":"β转角由几个残基组成？哪些残基常见？","a":"4个残基；Gly/Pro常见，第一个C=O与第四个N—H形成氢键。","e":"4残基/Gly/Pro。","src":"老师PPT·针对性自测"},"i":26,"exam":{"kind":"mcq","id":"bc03_q12","q":"β转角通常由几个残基组成？","o":["A. 4","B. 2","C. 8","D. 10"],"a":"A","e":"β转角由4个残基组成，Gly/Pro常见。","src":"页级选择题"},"imageExplain":"这张图主要在讲：β转角由4个残基组成，第一个C=O与第四个N—H形成氢键。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 三)β 转角和β 凸 起 - 转角由四个氨基酸残基组成，弯曲处的第一个氨基酸 残基的 -C=O 和第四个残基的– N-H 之间形成氢键，形 成一个不很稳定的环状结构；这类结构主要存在于球状蛋白分子中。"},{"sec":"第3章 · 三、二级结构","title":"无规卷曲","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。无规卷曲没有规则重复的φ/ψ，但仍有确定构象；常位于表面/连接区，参与柔性。","img":"assets/img/bc02/full132.jpg","points":["( 四) 无规卷曲 无一定的规则, 但对一定的球蛋白而言, 特定的区域有 特定的卷曲方式."],"i":27,"check":{"kind":"short","id":"bc03_c27_check","q":"无规卷曲是否没有确定构象？","a":"不是；它没有规则重复的φ/ψ，但仍有确定、较柔性的构象。","e":"有确定构象。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q13","q":"无规卷曲的正确描述是？","o":["A. 仍有确定构象","B. 完全无结构","C. 只含β折叠","D. 只含α螺旋"],"a":"A","e":"无规卷曲也有确定构象，只是不规整。","src":"页级选择题"},"imageExplain":"这张图主要在讲：无规卷曲没有规则重复的φ/ψ，但仍有确定构象。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 四) 无规卷曲 无一定的规则, 但对一定的球蛋白而言, 特定的区域有 特定的卷曲方式.。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲4：纤维状蛋白质","notes":"【图源】AI串讲配图/原书图。α-角蛋白、丝心蛋白、胶原蛋白、弹性蛋白；结构决定力学性质。","points":["α-角蛋白：α螺旋卷曲螺旋，富含Cys/二硫键。","丝心蛋白：反平行β折叠，Gly-Ala重复。","胶原蛋白：Gly-X-Y三股螺旋，羟脯氨酸/羟赖氨酸。","弹性蛋白：无规/β转角，弹性纤维。"],"table":[["蛋白","二级结构","特点"],["α-角蛋白","α螺旋卷曲螺旋","Cys/二硫键"],["丝心蛋白","反平行β折叠","Gly-Ala重复"],["胶原蛋白","三股螺旋","Gly-X-Y，交联"],["弹性蛋白","无规/β转角","弹性"]],"tableTitle":"纤维状蛋白比较","check":{"kind":"short","id":"bc03_ai4_check","q":"胶原蛋白的氨基酸重复序列和结构特点是什么？","a":"Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋；羟脯氨酸/羟赖氨酸参与稳定和交联。","e":"记Gly-X-Y和三股螺旋。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai4_exam","q":"胶原蛋白的特征重复序列是？","o":["A. Gly-X-Y","B. Gly-Ala","C. Lys-Arg","D. Phe-Trp"],"a":"A","e":"胶原蛋白为(Gly-X-Y)n，Gly占1/3。","src":"AI补充·选择"},"i":28,"img":"assets/img/bc02/full141.jpg","imageExplain":"这张胶原蛋白图说明纤维状蛋白怎样靠重复序列和交联形成强韧纤维：Gly-X-Y三股螺旋，羟脯氨酸稳定，分子间交联提供强度。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"纤维状蛋白质：总览","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。纤维状蛋白呈长条/纤维，提供结构支撑；包括α-角蛋白、丝心蛋白、胶原蛋白、弹性蛋白等。","img":"assets/img/bc02/full133.jpg","points":["纤维状蛋白长条/纤维。","角蛋白/丝心蛋白/胶原/弹性蛋白。","结构支撑。"],"i":29,"exam":{"kind":"mcq","id":"bc03_q18","q":"下列属于纤维状蛋白的是？","o":["A. 胶原蛋白","B. 血红蛋白","C. 肌红蛋白","D. 溶菌酶"],"a":"A","e":"胶原蛋白是纤维状结构蛋白。","src":"页级选择题"},"imageExplain":"这张图主要在讲：纤维状蛋白呈长条/纤维，提供结构支撑。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：纤维状蛋白长条/纤维。；角蛋白/丝心蛋白/胶原/弹性蛋白。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白：α螺旋卷曲螺旋，富含Cys，二硫键交联；皮肤/毛发/角。","img":"assets/img/bc02/full134.jpg","points":["( 一) α- 角蛋白 纤丝"],"i":30,"check":{"kind":"short","id":"bc03_c30_check","q":"α-角蛋白靠什么共价键稳定纤维？","a":"半胱氨酸之间的二硫键；α螺旋形成卷曲螺旋。","e":"二硫键。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q14","q":"α-角蛋白中稳定纤维的主要共价键是？","o":["A. 二硫键","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"α-角蛋白富含Cys，二硫键稳定纤维。","src":"页级选择题"},"imageExplain":"这张图主要在讲：α-角蛋白：α螺旋卷曲螺旋，富含Cys，二硫键交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 一) α- 角蛋白 纤丝。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白的原纤维","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白原纤维：两条α螺旋形成卷曲螺旋→protofilament→microfibril；二硫键稳定。","img":"assets/img/bc02/full135.jpg","points":["原纤维 初原纤维 卷曲的螺旋"],"i":31,"check":{"kind":"short","id":"bc03_c31_check","q":"α-角蛋白原纤维的装配层次？","a":"α螺旋→卷曲螺旋→protofilament→microfibril；二硫键稳定。","e":"层次装配。","src":"老师PPT·针对性自测"},"imageExplain":"这张图主要在讲：α-角蛋白原纤维：两条α螺旋形成卷曲螺旋→protofilament→microfibril。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原纤维 初原纤维 卷曲的螺旋。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白结构图（一）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白结构图一：卷曲螺旋的七残基重复（heptad）与疏水界面。","img":"assets/img/bc02/full136.jpg","points":["卷曲螺旋七残基重复。","疏水界面稳定。","二硫键。"],"i":32,"imageExplain":"这张图主要在讲：α-角蛋白结构图一：卷曲螺旋的七残基重复（heptad）与疏水界面。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：卷曲螺旋七残基重复。；疏水界面稳定。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白结构图（二）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白结构图二：多股卷曲螺旋装配成原纤维。","img":"assets/img/bc02/full137.jpg","points":["多股卷曲螺旋。","原纤维层次。","角蛋白。"],"i":33,"imageExplain":"这张图主要在讲：α-角蛋白结构图二：多股卷曲螺旋装配成原纤维。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：多股卷曲螺旋。；原纤维层次。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"α-角蛋白结构图（三）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。α-角蛋白结构图三：原纤维/微原纤维的层次与二硫键交联。","img":"assets/img/bc02/full138.jpg","points":["原纤维/微原纤维。","二硫键交联。","角蛋白。"],"i":34,"imageExplain":"这张图主要在讲：α-角蛋白结构图三：原纤维/微原纤维的层次与二硫键交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原纤维/微原纤维。；二硫键交联。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"丝心蛋白和其他β-角蛋白","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。丝心蛋白：反平行β折叠，Gly-Ala重复；小侧链允许片层紧密堆积，纤维强韧。","img":"assets/img/bc02/full139.jpg","points":["( 二) 丝心蛋白和其他β- 角蛋白：β 折叠片蛋白质"],"i":35,"check":{"kind":"short","id":"bc03_c35_check","q":"丝心蛋白的重复序列和二级结构？","a":"Gly-Ala重复；反平行β折叠，小侧链使片层紧密堆积。","e":"Gly-Ala/反平行β。","src":"老师PPT·针对性自测"},"exam":{"kind":"mcq","id":"bc03_q15","q":"丝心蛋白的重复序列和结构是？","o":["A. Gly-Ala，反平行β折叠","B. Gly-X-Y，三股螺旋","C. 全是α螺旋","D. 无规卷曲"],"a":"A","e":"丝心蛋白为Gly-Ala重复的反平行β折叠。","src":"页级选择题"},"imageExplain":"这张图主要在讲：丝心蛋白：反平行β折叠，Gly-Ala重复。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：( 二) 丝心蛋白和其他β- 角蛋白：β 折叠片蛋白质。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"丝心蛋白结构图","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。丝心蛋白结构图：反平行β片层沿纤维轴排列，Gly/Ala交替。","img":"assets/img/bc02/full140.jpg","points":["反平行β片层。","Gly-Ala重复。","纤维强韧。"],"i":36,"imageExplain":"这张图主要在讲：丝心蛋白结构图：反平行β片层沿纤维轴排列，Gly/Ala交替。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：反平行β片层。；Gly-Ala重复。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白：三股螺旋","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白：Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋；羟脯氨酸/羟赖氨酸稳定。","img":"assets/img/bc02/full141.jpg","points":["( 三) 胶原蛋白： 胶原蛋白的二级 结构是由三条肽链组成 的三股螺旋，这是一种 右手超螺旋结构","螺距 为8.6nm ，每圈每股包 含30 个残基","其中每 一股螺旋又是一种特殊 的左手螺旋，螺距为 0.95nm ，每一螺圈含 3.3 个残基, 每一残基 沿轴向的距离为 0.29nm"],"check":{"kind":"short","id":"bc03_c37_check","q":"胶原蛋白的重复序列和螺旋结构？","a":"Gly-X-Y重复；三条左手螺旋形成右手三股超螺旋，羟脯氨酸稳定。","e":"Gly-X-Y/三股螺旋。","src":"老师PPT·针对性自测"},"i":37,"exam":{"kind":"mcq","id":"bc03_q16","q":"胶原蛋白的特征重复序列是？","o":["A. Gly-X-Y","B. Gly-Ala","C. Lys-Arg","D. Phe-Trp"],"a":"A","e":"胶原蛋白为(Gly-X-Y)n，Gly占1/3。","src":"页级选择题"},"imageExplain":"这张图在讲胶原蛋白的“三股螺旋”。三条多肽链各形成左手螺旋，再互相缠绕成右手超螺旋；核心空间很小，所以每隔两个残基就必须出现Gly（Gly-X-Y重复），Gly占1/3。羟脯氨酸/羟赖氨酸通过氢键和交联稳定三股螺旋。看图先找三条链、Gly重复和羟脯氨酸。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"原胶原蛋白分子","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。原胶原蛋白：三股螺旋、端肽；分子间交联形成胶原纤维。","img":"assets/img/bc02/full142.jpg","points":["原胶原蛋白分子 在胶原纤维中都 是有规则地按四 分之一错位，首 尾相接，并行排 列组成纤维束","这样通过1 ／4 错位排列便形成 间隔一定的（大 约70nm) 电子 密度区域，而呈 现横纹区带"],"check":{"kind":"short","id":"bc03_c38_check","q":"原胶原分子的结构和交联意义？","a":"三股螺旋+端肽；分子间交联形成胶原纤维，提供强度。","e":"三股螺旋/交联。","src":"老师PPT·针对性自测"},"i":38,"imageExplain":"这张图主要在讲：原胶原蛋白：三股螺旋、端肽。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原胶原蛋白分子 在胶原纤维中都 是有规则地按四 分之一错位，首 尾相接，并行排 列组成纤维束；这样通过1 ／4 错位排列便形成 间隔一定的（大 约70nm) 电子 密度区域，而呈 现横纹区带。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白结构图（一）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白结构图一：三股螺旋的轴向排列与Gly重复。","img":"assets/img/bc02/full143.jpg","points":["三股螺旋。","Gly-X-Y重复。","羟脯氨酸。"],"i":39,"imageExplain":"这张图主要在讲：胶原蛋白结构图一：三股螺旋的轴向排列与Gly重复。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：三股螺旋。；Gly-X-Y重复。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白结构图（二）","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白结构图二：原胶原分子组装成纤维。","img":"assets/img/bc02/full144.jpg","points":["原胶原组装。","纤维形成。","交联。"],"i":40,"imageExplain":"这张图主要在讲：胶原蛋白结构图二：原胶原分子组装成纤维。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原胶原组装。；纤维形成。。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白的生物学功能","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原蛋白提供机械强度，存在于皮肤/骨/腱/软骨；维生素C参与羟化，缺乏影响交联。","img":"assets/img/bc02/full145.jpg","points":["胶原蛋白属于结构蛋白质，使骨、腱、软骨和皮肤具有机械强度","胶 原蛋白至少包括四种类型，称胶原蛋白I 、Ⅱ、Ⅲ和Ⅳ","腱的胶原纤维具有 很高的抗张强度(tensile strength) ，约为20-30kg ／mm2 ，相当于 12 号冷拉钢丝的拉力"],"check":{"kind":"short","id":"bc03_c41_check","q":"胶原蛋白的主要功能和维生素C的作用？","a":"提供机械强度；维生素C参与脯氨酸/赖氨酸羟化，缺乏影响交联。","e":"结构支撑/维生素C。","src":"老师PPT·针对性自测"},"i":41,"exam":{"kind":"mcq","id":"bc03_q24","q":"胶原蛋白的主要功能是？","o":["A. 结构支撑","B. 运输氧","C. 催化反应","D. 免疫防御"],"a":"A","e":"胶原蛋白为结构蛋白，提供机械强度。","src":"页级选择题"},"imageExplain":"这张图主要在讲：胶原蛋白提供机械强度，存在于皮肤/骨/腱/软骨。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：胶原蛋白属于结构蛋白质，使骨、腱、软骨和皮肤具有机械强度；胶 原蛋白至少包括四种类型，称胶原蛋白I 、Ⅱ、Ⅲ和Ⅳ。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白的共价交联","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原交联：赖氨酰氧化酶氧化赖氨酸/羟赖氨酸，形成醛基，缩合成交联；随年龄增加。","img":"assets/img/bc02/full146.jpg","points":["赖氨酰氧化酶。","醛基交联。","随年龄增加。"],"i":42,"exam":{"kind":"mcq","id":"bc03_q17","q":"胶原蛋白交联形成的关键氨基酸衍生物是？","o":["A. 羟赖氨酸/赖氨酸","B. 色氨酸","C. 半胱氨酸","D. 组氨酸"],"a":"A","e":"羟赖氨酸参与形成吡啶啉等交联。","src":"页级选择题"},"imageExplain":"这张图在讲胶原纤维怎样“焊牢”。赖氨酰氧化酶把赖氨酸/羟赖氨酸侧链的—NH₂氧化成醛基；醛基再与相邻链的氨基缩合，形成 Schiff 碱/吡啶啉等交联。交联越多，胶原越刚、越难拉伸；随年龄增加交联增多。看图抓住“酶氧化→醛基→缩合→交联”。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"胶原蛋白交联图","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。胶原交联图：分子间/分子内交联，吡啶啉等成熟交联。","img":"assets/img/bc02/full147.jpg","points":["分子间/内交联。","吡啶啉。","组织刚性。"],"i":43,"imageExplain":"这张图在讲胶原分子之间/内部的交联位置。先找两条相邻的原胶原分子，再看端肽区或螺旋区的醛基如何与另一条链的 Lys/Hyl 缩合；成熟交联如吡啶啉把分子“钉”在一起。看图时把“分子间交联”与“组织强度/年龄”联系起来。"},{"sec":"第3章 · 四、纤维状蛋白质","title":"吡啶啉交联","notes":"【图源】老师第5章PPT原页（部分为原书图/重绘）。吡啶啉由原胶原N端与相邻C端形成，是成熟交联；随年龄增多，增加组织刚性。","img":"assets/img/bc02/full148.jpg","points":["吡啶啉是由一个 原胶原的N 末端 区和另一个相邻 的原胶原的C 末 端区之间形成","随着年龄的增长， 胶原蛋白之间的交 联键会增多"],"check":{"kind":"short","id":"bc03_c44_check","q":"吡啶啉交联如何形成？有什么意义？","a":"原胶原N端与相邻C端交联形成；随年龄增多，增加组织刚性。","e":"成熟交联/刚性。","src":"老师PPT·针对性自测"},"i":44,"imageExplain":"这张图主要在讲：吡啶啉由原胶原N端与相邻C端形成，是成熟交联。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：吡啶啉是由一个 原胶原的N 末端 区和另一个相邻 的原胶原的C 末 端区之间形成；随着年龄的增长， 胶原蛋白之间的交 联键会增多。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲5：超二级结构与结构域","notes":"【图源】AI串讲配图/原书图。超二级结构是二级结构的组合（βαβ、ββ、αα）；结构域是三级结构中相对独立的折叠区。","points":["常见motif：βαβ、ββ、αα、β转角组合。","结构域：相对独立折叠、常具独立功能/活性位点。","结构域可重组/演化，是蛋白质进化的模块。","例子：免疫球蛋白折叠、EF手、锌指。"],"check":{"kind":"short","id":"bc03_ai5_check","q":"什么是超二级结构和结构域？","a":"超二级结构是相邻二级结构的组合（如βαβ）；结构域是三级结构中相对独立、常具功能的折叠区。","e":"motif vs domain。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai5_exam","q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸结构"],"a":"A","e":"βαβ是二级结构的组合，属于超二级结构/motif。","src":"AI补充·选择"},"i":45,"img":"assets/img/bc03book/fig-domains.png","imageExplain":"这张图把motif（βαβ、ββ、αα）和domain分开：motif是二级结构的组合，domain是相对独立、常具功能的折叠区。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲6：球状蛋白三级结构","notes":"【图源】AI串讲配图/原书图。疏水核心+亲水表面；结构域组合；活性位点常在裂隙。","points":["疏水残基埋在内核，亲水残基在表面。","三级结构由弱作用力和二硫键稳定。","球状蛋白常由多个结构域组成。","活性位点常位于结构域之间/表面裂隙。"],"check":{"kind":"short","id":"bc03_ai6_check","q":"球状蛋白三级结构为什么常形成疏水核心？","a":"疏水残基埋入内部可减少水化熵损失，是折叠的主要驱动力；亲水残基朝向表面。","e":"疏水作用驱动。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai6_exam","q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心是球状蛋白稳定因素。","src":"AI补充·选择"},"i":46,"img":"assets/img/bc03book/fig-globular.png","imageExplain":"这张溶菌酶图说明球状蛋白：α螺旋/β折叠/转角/无规卷曲组合，疏水核心在内部，亲水表面朝外，活性位点在表面裂隙。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲7：膜蛋白结构","notes":"【图源】AI串讲配图/原书图。膜内在蛋白/膜外周蛋白；跨膜α螺旋或β桶。","points":["膜内在蛋白：跨膜段多为α螺旋，少数β桶。","膜外周蛋白：靠离子键/氢键附着表面。","跨膜段预测：疏水指数/正电荷内规则。","例子：细菌视紫红质（7次跨膜α螺旋）、孔蛋白（β桶）。"],"check":{"kind":"short","id":"bc03_ai7_check","q":"膜内在蛋白的跨膜段通常是什么结构？","a":"多为跨膜α螺旋；孔蛋白等为β桶。","e":"记α螺旋/β桶。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai7_exam","q":"细菌视紫红质的跨膜结构是？","o":["A. 7次跨膜α螺旋","B. β桶","C. 单层β折叠","D. 无跨膜段"],"a":"A","e":"细菌视紫红质为7次跨膜α螺旋。","src":"AI补充·选择"},"i":47,"img":"assets/img/bc03book/fig-membrane.png","imageExplain":"这张血型糖蛋白图说明单次跨膜α螺旋怎样锚定在脂双层中，膜外结构域带糖链；7次跨膜和β桶是另外两类常见结构。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲8：四级结构与亚基缔合","notes":"【图源】AI串讲配图/原书图。四级结构=亚基的种类、数目和空间排布；亚基间主要靠疏水作用、氢键、离子键，有时二硫键。","points":["四级结构：多个亚基通过非共价键缔合；亚基可相同/不同。","驱动力：疏水作用为主，氢键/离子键提供专一性；二硫键可稳定。","对称性：C4、D2等；同种/异种缔合。","优势：稳定性、遗传经济、活性中心组装、协同/别构。"],"check":{"kind":"short","id":"bc03_ai8_check","q":"四级结构的定义和主要驱动力是什么？","a":"亚基的种类、数目和空间排布；主要驱动力是疏水作用，氢键/离子键提供专一性。","e":"四级=亚基组装。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai8_exam","q":"稳定四级结构的主要驱动力通常是？","o":["A. 疏水作用","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"亚基界面疏水作用为主，氢键/离子键提供专一性。","src":"AI补充·选择"},"i":48,"img":"assets/img/bc03ai/fourlevel.svg","imageExplain":"这张图把四级结构放在最后：亚基通过疏水作用/氢键/离子键组装，形成C4/D2等对称性；别构和协同就来自亚基间构象变化。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲9：蛋白质变性","notes":"【图源】AI串讲配图/原书图。变性是物理/化学因素破坏次级键，导致天然构象解体；一级结构不断裂。","points":["变性：生物活性丧失、溶解度降低、黏度增加、侧链暴露。","实质：次级键被破坏，肽键/二硫键通常不断裂，一级结构保留。","变性剂：尿素/盐酸胍（氢键）、SDS（疏水）、热、极端pH、有机溶剂、重金属。","可逆 vs 不可逆；复性是恢复天然构象和活性。"],"check":{"kind":"short","id":"bc03_ai9_check","q":"蛋白质变性的实质是什么？一级结构会破坏吗？","a":"次级键被破坏、天然构象解体；一般不断裂肽键，一级结构保留。","e":"变性≠水解。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai9_exam","q":"蛋白质变性通常不涉及？","o":["A. 肽键断裂","B. 氢键破坏","C. 疏水作用破坏","D. 构象改变"],"a":"A","e":"变性主要破坏次级键，肽键通常保留。","src":"AI补充·选择"},"i":49,"img":"assets/img/bc03ai/denature.svg","imageExplain":"这张图说明变性：热/尿素/SDS破坏次级键，天然构象解体，活性丧失；去除变性剂后有些蛋白可复性。"},{"sec":"第3章 · AI考点串讲","title":"AI串讲9：折叠与结构预测","notes":"【图源】AI串讲配图/原书图。Anfinsen：序列决定结构；折叠受分子伴侣、折叠酶和细胞环境影响；预测方法从Chou-Fasman到AlphaFold。","points":["Anfinsen核糖核酸酶实验：变性后去变性剂可复性，说明序列决定结构。","折叠漏斗：多路径、能量下降；分子伴侣防止聚集，PDI/PPI帮助二硫键/脯氨酸异构。","二级结构预测：Chou-Fasman/GOR；三级结构：同源建模/Threading；AlphaFold。","预测需实验验证（CD、NMR、晶体/电镜）。"],"check":{"kind":"short","id":"bc03_ai9b_check","q":"Anfinsen实验说明什么？","a":"蛋白质的氨基酸序列决定其三维结构和活性；变性后可复性。","e":"序列决定结构。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_ai9b_exam","q":"Anfinsen核糖核酸酶复性实验说明？","o":["A. 序列决定结构","B. 变性必然不可逆","C. 肽键断裂","D. 二硫键不能重建"],"a":"A","e":"变性去除后活性恢复，说明一级序列决定天然构象。","src":"AI补充·选择"},"i":50,"img":"assets/img/bc03ai/folding.svg","imageExplain":"这张漏斗图说明折叠不是随机搜索：多条路径沿能量下降到达天然态；分子伴侣/折叠酶辅助，Chou-Fasman/AlphaFold用于预测。"},{"sec":"第3章 · AI图解","title":"AI图解1：超二级结构与结构域","img":"assets/img/bc03ai/domains.svg","notes":"【图源】AI按原书内容重绘。超二级结构是若干相邻二级结构的组合（βαβ、ββ、αα）；结构域是三级结构中相对独立、常具功能的折叠区。","points":["βαβ：β-α-β组合，常见于核苷酸结合蛋白。","ββ：发夹/β-转角连接；αα：卷曲螺旋/螺旋束。","结构域可独立折叠、重组和演化，是功能模块。","考点：区分motif与domain；例子：Ig折叠、EF手、锌指。"],"check":{"kind":"short","id":"bc03_d1_check","q":"超二级结构和结构域有什么区别？","a":"超二级结构是相邻二级结构的组合；结构域是三级结构中相对独立、常具功能的折叠区。","e":"motif vs domain。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d1_exam","q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸结构"],"a":"A","e":"βαβ是二级结构的组合，属于超二级结构/motif。","src":"AI图解·选择"},"i":51,"imageExplain":"这张图主要在讲：超二级结构是若干相邻二级结构的组合（βαβ、ββ、αα）。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：βαβ：β-α-β组合，常见于核苷酸结合蛋白。；ββ：发夹/β-转角连接；αα：卷曲螺旋/螺旋束。。"},{"sec":"第3章 · AI图解","title":"AI图解2：球状蛋白三级结构","img":"assets/img/bc03ai/globular.svg","notes":"【图源】AI按原书内容重绘。球状蛋白通常疏水残基埋在内核、亲水残基在表面；结构域组合形成裂隙状活性位点。","points":["疏水核心是折叠主要驱动力；亲水/带电残基朝外。","三级结构由疏水作用、氢键、离子键、范德华力、二硫键稳定。","球状蛋白常含多个结构域，活性位点常在结构域之间/表面裂隙。","考点：疏水核心、结构域、活性位点。"],"check":{"kind":"short","id":"bc03_d2_check","q":"球状蛋白为什么形成疏水核心？","a":"疏水残基埋入内部可减少水化熵损失，是折叠主要驱动力；亲水残基朝向表面。","e":"疏水作用驱动。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d2_exam","q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心是球状蛋白稳定因素。","src":"AI图解·选择"},"i":52,"imageExplain":"这张图主要在讲：球状蛋白通常疏水残基埋在内核、亲水残基在表面。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：疏水核心是折叠主要驱动力；亲水/带电残基朝外。；三级结构由疏水作用、氢键、离子键、范德华力、二硫键稳定。。"},{"sec":"第3章 · AI图解","title":"AI图解3：膜蛋白结构","img":"assets/img/bc03ai/membrane.svg","notes":"【图源】AI按原书内容重绘。膜内在蛋白跨膜段多为α螺旋，少数为β桶；膜外周蛋白靠离子键/氢键附着表面。","points":["膜内在蛋白：7次跨膜α螺旋（细菌视紫红质）或β桶（孔蛋白）。","膜外周蛋白：可溶性球状蛋白，靠静电/氢键结合表面。","跨膜段预测：疏水指数、正电荷内规则。","考点：α螺旋/β桶、内外周蛋白、拓扑。"],"check":{"kind":"short","id":"bc03_d3_check","q":"膜内在蛋白的跨膜段通常是什么结构？","a":"多为跨膜α螺旋，少数为β桶（孔蛋白）；膜外周蛋白靠离子键/氢键附着。","e":"α螺旋/β桶。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d3_exam","q":"孔蛋白的跨膜结构是？","o":["A. β桶","B. 7次跨膜α螺旋","C. 单层α螺旋","D. 无跨膜段"],"a":"A","e":"孔蛋白为β桶结构。","src":"AI图解·选择"},"i":53,"imageExplain":"这张图主要在讲：膜内在蛋白跨膜段多为α螺旋，少数为β桶。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：膜内在蛋白：7次跨膜α螺旋（细菌视紫红质）或β桶（孔蛋白）。；膜外周蛋白：可溶性球状蛋白，靠静电/氢键结合表面。。"},{"sec":"第3章 · AI图解","title":"AI图解4：四级结构与亚基缔合","img":"assets/img/bc03ai/fourlevel.svg","notes":"【图源】AI按原书内容重绘。四级结构是亚基的种类、数目和空间排布；亚基间主要靠疏水作用、氢键、离子键，有时二硫键。","points":["四级结构=亚基组装；亚基可相同/不同。","驱动力：疏水作用为主，氢键/离子键提供专一性。","对称性：C4、D2；同种/异种缔合。","优势：稳定性、遗传经济、活性中心组装、协同/别构。"],"check":{"kind":"short","id":"bc03_d4_check","q":"四级结构的定义和主要驱动力？","a":"亚基种类/数目/空间排布；主要驱动力是疏水作用，氢键/离子键提供专一性。","e":"四级=亚基组装。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d4_exam","q":"稳定四级结构的主要驱动力通常是？","o":["A. 疏水作用","B. 肽键","C. 磷酸二酯键","D. 糖苷键"],"a":"A","e":"亚基界面疏水作用为主。","src":"AI图解·选择"},"i":54,"imageExplain":"这张图主要在讲：四级结构是亚基的种类、数目和空间排布。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：四级结构=亚基组装；亚基可相同/不同。；驱动力：疏水作用为主，氢键/离子键提供专一性。。"},{"sec":"第3章 · AI图解","title":"AI图解5：蛋白质变性与复性","img":"assets/img/bc03ai/denature.svg","notes":"【图源】AI按原书内容重绘。变性是物理/化学因素破坏次级键，天然构象解体；一级结构通常保留；去除变性剂可复性。","points":["变性：活性丧失、溶解度下降、黏度增加、侧链暴露。","实质：次级键破坏；肽键/二硫键通常不断裂，一级结构保留。","变性剂：尿素/盐酸胍、SDS、热、极端pH、有机溶剂、重金属。","复性：去除变性剂恢复天然构象；Anfinsen实验。"],"check":{"kind":"short","id":"bc03_d5_check","q":"蛋白质变性的实质是什么？一级结构会破坏吗？","a":"次级键破坏、天然构象解体；一般不断裂肽键，一级结构保留。","e":"变性≠水解。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d5_exam","q":"蛋白质变性通常不涉及？","o":["A. 肽键断裂","B. 氢键破坏","C. 疏水作用破坏","D. 构象改变"],"a":"A","e":"变性主要破坏次级键，肽键通常保留。","src":"AI图解·选择"},"i":55,"imageExplain":"这张图主要在讲：变性是物理/化学因素破坏次级键，天然构象解体。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：变性：活性丧失、溶解度下降、黏度增加、侧链暴露。；实质：次级键破坏；肽键/二硫键通常不断裂，一级结构保留。。"},{"sec":"第3章 · AI图解","title":"AI图解6：折叠与结构预测","img":"assets/img/bc03ai/folding.svg","notes":"【图源】AI按原书内容重绘。Anfinsen：序列决定结构；折叠经漏斗状能量景观，受分子伴侣/折叠酶辅助；预测从Chou-Fasman到AlphaFold。","points":["Anfinsen：变性核糖核酸酶去除变性剂可复性。","折叠漏斗：多路径、能量下降；分子伴侣防聚集；PDI/PPI辅助。","二级结构预测：Chou-Fasman/GOR；三级：同源建模/Threading；AlphaFold。","预测需实验验证（CD/NMR/晶体/电镜）。"],"check":{"kind":"short","id":"bc03_d6_check","q":"Anfinsen实验说明什么？","a":"氨基酸序列决定三维结构和活性；变性后可复性。","e":"序列决定结构。","src":"AI图解·自测"},"exam":{"kind":"mcq","id":"bc03_d6_exam","q":"Anfinsen核糖核酸酶复性实验说明？","o":["A. 序列决定结构","B. 变性不可逆","C. 肽键断裂","D. 二硫键不能重建"],"a":"A","e":"去除变性剂后活性恢复，说明一级序列决定构象。","src":"AI图解·选择"},"i":56,"imageExplain":"这张图主要在讲：Anfinsen：序列决定结构。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：Anfinsen：变性核糖核酸酶去除变性剂可复性。；折叠漏斗：多路径、能量下降；分子伴侣防聚集；PDI/PPI辅助。。"},{"sec":"第3章 · 公式精讲","title":"公式1：Bragg方程（X射线）","notes":"先认公式，再认每个字母和单位，最后代一个数。不要死背符号。","points":["公式：2d sinθ = nλ。","d=晶面间距；θ=掠射角；λ=X射线波长；n=衍射级数（1,2,3…）。","怎么用：已知λ、θ求d。例：λ=0.154 nm，θ=10°，n=1 → d=0.154/(2×sin10°)≈0.444 nm。","单位：d和λ都用nm；θ用度；sinθ无单位。","易错：θ不是2θ；公式里的2不能丢。"],"check":{"kind":"short","id":"bc03_f1_check","q":"Bragg方程中d、θ、λ分别是什么？","a":"d晶面间距，θ掠射角，λ波长；2d sinθ=nλ。","e":"记符号和单位。","src":"公式精讲·自测"},"i":57},{"sec":"第3章 · 公式精讲","title":"公式2：α螺旋长度","notes":"α螺旋每圈3.6个残基、螺距0.54 nm；也可以按每残基上升0.15 nm算。","points":["公式：L≈(n/3.6)×0.54 nm，或L≈n×0.15 nm。","n=残基数；3.6=每圈残基数；0.54 nm=每圈螺距；0.15 nm=每残基上升。","例：n=36 → 36/3.6=10圈 → 10×0.54=5.4 nm；36×0.15也=5.4 nm。","易错：0.54 nm是“每圈”，不是“每残基”；0.15 nm才是每残基。"],"check":{"kind":"short","id":"bc03_f2_check","q":"36个残基的α螺旋长度约多少？","a":"36/3.6=10圈；10×0.54=5.4 nm（或36×0.15=5.4 nm）。","e":"先算圈数或直接乘0.15。","src":"公式精讲·自测"},"i":58},{"sec":"第3章 · 公式精讲","title":"公式3：β折叠长度","notes":"β折叠是伸展链，每个残基沿轴约0.35 nm；长度按残基数乘0.35 nm估算。","points":["公式：L≈n×0.35 nm。","n=残基数；0.35 nm=β折叠中每残基沿轴的距离。","例：n=20 → L≈7 nm。","对比：α螺旋每残基0.15 nm；β折叠更伸展，所以每残基0.35 nm。","易错：不要把β折叠代成0.15 nm。"],"check":{"kind":"short","id":"bc03_f3_check","q":"β折叠每残基轴心距多少？20残基长度约多少？","a":"0.35 nm/残基；20×0.35≈7 nm。","e":"β折叠比α螺旋更伸展。","src":"公式精讲·自测"},"i":59},{"sec":"第3章 · 公式精讲","title":"公式4：折叠热力学 ΔG","notes":"ΔG=ΔH−TΔS。T一定要用开尔文；ΔG<0说明折叠稳定。","points":["公式：ΔG=ΔH−TΔS。","ΔH=焓变；ΔS=熵变；T=绝对温度（K）；ΔG<0→过程自发/稳定。","例：ΔH=−500 kJ/mol，ΔS=−1.15 kJ/(K·mol)，T=298 K → ΔG=−500−298×(−1.15)≈−157 kJ/mol。","符号：ΔS为负（折叠熵降低）；减去负值等于加上正项。","易错：T不能代25；ΔS不要漏负号。"],"check":{"kind":"short","id":"bc03_f4_check","q":"ΔH=−500，ΔS=−1.15，T=298 K，求ΔG。","a":"ΔG=−500−298×(−1.15)≈−157 kJ/mol；ΔG<0，折叠稳定。","e":"先算TΔS，注意负号。","src":"公式精讲·自测"},"i":60},{"sec":"第3章 · 公式精讲","title":"公式5：残基数与Chou-Fasman","notes":"N≈Mr/110用来估算残基数；Chou-Fasman不是代数公式，而是查倾向性表后滑窗打分。","points":["残基数：N≈Mr/110。例：Mr=240000 → N≈2182。","Chou-Fasman：查每个残基的Pα/Pβ/Pt；连续高Pα→α螺旋，高Pβ→β折叠，高Pt→β转角。","例：Q10结果：4–11 α；14–19 β；20–23 β转角；24–30 β。","易错：110只是平均残基质量，不是精确值；Chou-Fasman要滑窗，不是看单个残基。"],"check":{"kind":"short","id":"bc03_f5_check","q":"Mr=240000时残基数约多少？Chou-Fasman看哪三个参数？","a":"N≈240000/110≈2182；看Pα、Pβ、Pt。","e":"残基数估算+滑窗。","src":"公式精讲·自测"},"i":61},{"sec":"第3章 · 过程版","title":"过程版1：Bragg方程算晶面间距","notes":"Bragg方程：2d sinθ=nλ；先统一单位，再代入。","points":["公式：2d sinθ=nλ。","n=1时d=λ/(2sinθ)。","λ=0.154 nm，θ=10°，d≈0.444 nm。","θ为掠射角，d为晶面间距。"],"check":{"kind":"short","id":"bc03_p1_check","q":"λ=0.154 nm，θ=10°，n=1，求d。","a":"d=0.154/(2×sin10°)≈0.154/0.347≈0.444 nm。","e":"先算sinθ，再代入。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p1_exam","q":"Bragg方程中d代表？","o":["A. 晶面间距","B. 波长","C. 衍射角","D. 电子密度"],"a":"A","e":"d为晶面间距；λ为波长，θ为掠射角。","src":"AI补充·选择"},"i":62},{"sec":"第3章 · 过程版","title":"过程版2：α螺旋长度与氢键计算","notes":"α螺旋每圈3.6个残基、螺距0.54 nm；长度≈(n/3.6)×0.54 nm。","points":["每圈3.6残基；螺距0.54 nm。","n个残基长度≈(n/3.6)×0.54 nm。","i→i+4氢键稳定螺旋。","例：36残基≈10圈×0.54=5.4 nm。"],"check":{"kind":"short","id":"bc03_p2_check","q":"36个残基的α螺旋约多长？","a":"36/3.6=10圈；10×0.54 nm=5.4 nm。","e":"先算圈数，再乘螺距。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p2_exam","q":"α螺旋每圈约含多少个残基？","o":["A. 3.6","B. 2.0","C. 4.0","D. 10"],"a":"A","e":"α螺旋3.6残基/圈，螺距0.54 nm。","src":"AI补充·选择"},"i":63},{"sec":"第3章 · 过程版","title":"过程版3：纤维状蛋白识别","notes":"看重复序列、二级结构、交联方式：α-角蛋白/丝心蛋白/胶原蛋白各有指纹。","points":["α-角蛋白：α螺旋卷曲螺旋，Cys/二硫键。","丝心蛋白：反平行β折叠，Gly-Ala重复。","胶原蛋白：Gly-X-Y三股螺旋，羟脯氨酸。","弹性蛋白：无规/β转角，弹性。"],"check":{"kind":"short","id":"bc03_p3_check","q":"Gly-X-Y重复、三股螺旋提示哪种蛋白？","a":"胶原蛋白；Gly占1/3，羟脯氨酸/羟赖氨酸参与稳定。","e":"序列+结构双指纹。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p3_exam","q":"Gly-Ala重复、反平行β折叠提示？","o":["A. 丝心蛋白","B. 胶原蛋白","C. α-角蛋白","D. 弹性蛋白"],"a":"A","e":"丝心蛋白为Gly-Ala重复的反平行β折叠。","src":"AI补充·选择"},"i":64},{"sec":"第3章 · 过程版","title":"过程版4：结构测定方法选择","notes":"【图源】AI示意图。先看样品：晶体→X射线；溶液小蛋白→NMR；二级结构→CD；大复合物/膜蛋白→冷冻电镜。","points":["晶体且需高分辨率→X射线。","溶液、动态、小到中等蛋白→NMR。","快速判断二级结构→CD。","大复合物/膜蛋白→冷冻电镜。","综合验证：CD+NMR/晶体/电镜。"],"check":{"kind":"short","id":"bc03_p4_check","q":"一个难结晶的膜蛋白大复合物，优先选什么方法？","a":"冷冻电镜；可在近天然环境中解析大复合物/膜蛋白结构。","e":"难结晶+大复合物→电镜。","src":"AI补充·自测"},"exam":{"kind":"mcq","id":"bc03_p4_exam","q":"难结晶的膜蛋白大复合物优先选？","o":["A. 冷冻电镜","B. X射线衍射","C. CD","D. 超速离心"],"a":"A","e":"冷冻电镜适合大复合物和膜蛋白。","src":"AI补充·选择"},"i":65,"img":"assets/img/bc03ai/method-choice.svg","imageExplain":"这张图像一张“选方法”的流程图：先看样品能不能长晶体；能长晶体优先X射线；溶液中小蛋白用NMR；只想快速看二级结构用CD；难结晶的大复合物/膜蛋白用冷冻电镜。记住：样品状态决定方法，分辨率/动态需求决定组合。"},{"title":"原书页：超二级结构与结构域（p.114）","img":"assets/img/bc03book/domains.png","notes":"原书扫描页。重点看：超二级结构定义、三种主要motif（αα、βαβ、ββ）、结构域定义与四类结构域。","points":["原书图3-31/表3-5：motif与domain。","结构域四类：全α、全β、α/β、α+β。","结构域是独立折叠/功能单位。"],"check":{"kind":"short","id":"bc03_book1_check","q":"原书页中结构域大体分为哪四类？","a":"全α、全β、α/β、α+β四类。","e":"记二级结构种类及排列。","src":"原书页·自测"},"i":66,"imageExplain":"这张图主要在讲：重点看：超二级结构定义、三种主要motif（αα、βαβ、ββ）、结构域定义与四类结构域。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：原书图3-31/表3-5：motif与domain。；结构域四类：全α、全β、α/β、α+β。。"},{"title":"原书页：球状蛋白三级结构（p.118）","img":"assets/img/bc03book/globular.png","notes":"原书扫描页。重点看球状蛋白三级结构特征、疏水核心、活性位点空穴。","points":["多种二级结构元件；紧密球状/椭球。","疏水侧链埋内，亲水侧链朝外。","表面空穴常为活性位点。"],"check":{"kind":"short","id":"bc03_book2_check","q":"球状蛋白三级结构有哪些特征？","a":"含多种二级结构、紧密球状、疏水核心、表面活性位点空穴。","e":"四条特征。","src":"原书页·自测"},"i":67,"imageExplain":"这张图主要在讲：重点看球状蛋白三级结构特征、疏水核心、活性位点空穴。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：多种二级结构元件；紧密球状/椭球。；疏水侧链埋内，亲水侧链朝外。。"},{"title":"原书页：膜蛋白结构（p.125）","img":"assets/img/bc03book/membrane.png","notes":"原书扫描页。重点看膜周边/膜内在蛋白分类、单跨膜与7次跨膜、β桶。","points":["膜周边蛋白：靠静电/氢键附着。","膜内在蛋白：单跨膜或7次跨膜α螺旋。","孔蛋白等为β桶。"],"check":{"kind":"short","id":"bc03_book3_check","q":"膜内在蛋白的两种常见跨膜结构？","a":"单次/多次跨膜α螺旋；孔蛋白为β桶。","e":"α螺旋/β桶。","src":"原书页·自测"},"i":68,"imageExplain":"这张原书页在讲膜蛋白怎样“住在膜里”。先看脂双层：亲水头朝外、疏水尾朝内。膜内在蛋白的跨膜段多为α螺旋（如7次跨膜），少数是β桶；膜外周蛋白靠离子键/氢键贴在膜表面。看图先找跨膜段、膜内外两侧和糖链。"},{"title":"原书页：四级结构与对称性（p.129）","img":"assets/img/bc03book/fourlevel.png","notes":"原书扫描页。重点看四级结构定义、亚基缔合驱动力、对称性（C4/D2等）。","points":["四级=亚基种类/数目/空间排布。","疏水作用驱动，氢键/离子键提供专一性。","对称性：C4、D2等；同种/异种缔合。"],"check":{"kind":"short","id":"bc03_book4_check","q":"四级结构的主要驱动力和对称性例子？","a":"疏水作用为主；对称性如C4、D2。","e":"亚基组装。","src":"原书页·自测"},"i":69,"imageExplain":"这张原书页在讲“四级结构=亚基怎么排”。先看亚基种类、数目和空间排布；亚基之间主要靠疏水作用，氢键/离子键提供专一性。对称性如 C4、D2 说明相同亚基有规律排列；同种/异种缔合决定是闭合二聚体还是开放聚合。看图先找对称轴和亚基界面。"},{"title":"原书页：蛋白质变性（p.135）","img":"assets/img/bc03book/denature.png","notes":"原书扫描页。重点看变性定义、实质、现象、变性剂（尿素/SDS）和吴宪学说。","points":["变性：活性丧失、溶解度降低、构象解体。","实质：次级键破坏；一级结构保留。","变性剂：尿素/盐酸胍、SDS、热、极端pH。"],"check":{"kind":"short","id":"bc03_book5_check","q":"蛋白质变性的实质是什么？","a":"次级键被破坏，天然构象解体；肽键/一级结构通常保留。","e":"变性≠水解。","src":"原书页·自测"},"i":70,"imageExplain":"这张图主要在讲：重点看变性定义、实质、现象、变性剂（尿素/SDS）和吴宪学说。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：变性：活性丧失、溶解度降低、构象解体。；实质：次级键破坏；一级结构保留。。"},{"title":"原书页：Anfinsen复性实验（p.137）","img":"assets/img/bc03book/anfinsen.png","notes":"原书扫描页。重点看核糖核酸酶变性/复性、二硫键重建、序列决定结构。","points":["变性RNase（二硫键还原）失去活性。","去除变性剂/氧化后活性恢复。","说明一级序列决定天然构象。"],"check":{"kind":"short","id":"bc03_book6_check","q":"Anfinsen实验说明什么？","a":"蛋白质氨基酸序列决定其三维结构和活性；变性可复性。","e":"序列决定结构。","src":"原书页·自测"},"i":71,"imageExplain":"这张图主要在讲：重点看核糖核酸酶变性/复性、二硫键重建、序列决定结构。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：变性RNase（二硫键还原）失去活性。；去除变性剂/氧化后活性恢复。。"},{"title":"原书单图：超二级结构（图3-31）","img":"assets/img/bc03book/fig-domains.png","notes":"原书图3-31的单图裁切。看βαβ、ββ、αα等motif的二级结构组合方式；注意N/C端方向。","points":["motif=相邻二级结构的组合。","βαβ、ββ、αα是常见类型。","motif是三级结构的构件。"],"check":{"kind":"short","id":"bc03_fig1_check","q":"原书图3-31展示了哪些超二级结构？","a":"βαβ、ββ、αα等二级结构组合（motif）。","e":"看图记类型。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig1_exam","q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸"],"a":"A","e":"βαβ是二级结构组合，属于motif。","src":"原书单图·选择"},"i":72,"imageExplain":"这张图在讲“二级结构怎样组合成motif”。先看单个α螺旋/β折叠，再看它们怎样相邻组合：βαβ、ββ、αα等。motif不是独立功能单位，但它是三级结构的“积木”；多个motif再组装成结构域。看图先认二级结构元件，再看连接方式。"},{"title":"原书单图：溶菌酶三级结构（图3-38）","img":"assets/img/bc03book/fig-globular.png","notes":"原书图3-38的单图裁切。看溶菌酶中α螺旋、β折叠、β转角、无规卷曲如何组合成球状三级结构。","points":["球状蛋白含多种二级结构元件。","疏水核心、亲水表面。","活性位点位于表面裂隙。"],"check":{"kind":"short","id":"bc03_fig2_check","q":"溶菌酶图中可见哪些二级结构？","a":"α螺旋、β折叠、β转角、无规卷曲。","e":"多种元件组合。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig2_exam","q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心稳定三级结构。","src":"原书单图·选择"},"i":73,"imageExplain":"这张图主要在讲：看溶菌酶中α螺旋、β折叠、β转角、无规卷曲如何组合成球状三级结构。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：球状蛋白含多种二级结构元件。；疏水核心、亲水表面。。"},{"title":"原书单图：血型糖蛋白A跨膜（图3-46）","img":"assets/img/bc03book/fig-membrane.png","notes":"原书图3-46的单图裁切。看单次跨膜α螺旋、膜内外两侧结构域和糖链。","points":["单跨膜α螺旋锚定膜。","大部分蛋白位于膜一侧/两侧水环境。","膜外结构域可带糖链。"],"check":{"kind":"short","id":"bc03_fig3_check","q":"血型糖蛋白A的跨膜结构是什么？","a":"单次跨膜α螺旋；大部分位于膜外，带糖链。","e":"单跨膜。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig3_exam","q":"血型糖蛋白A属于？","o":["A. 单次跨膜蛋白","B. 7次跨膜蛋白","C. β桶","D. 膜外周蛋白"],"a":"A","e":"血型糖蛋白A为单次跨膜α螺旋。","src":"原书单图·选择"},"i":74,"imageExplain":"这张图主要在讲：看单次跨膜α螺旋、膜内外两侧结构域和糖链。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：单跨膜α螺旋锚定膜。；大部分蛋白位于膜一侧/两侧水环境。。"},{"title":"原书单图：尿素/盐酸胍变性","img":"assets/img/bc03book/fig-denature.png","notes":"原书变性示意图的单图裁切。看尿素/盐酸胍与主链竞争氢键，破坏次级键，使天然构象解体。","points":["尿素/盐酸胍竞争氢键。","SDS破坏疏水作用。","变性通常不破坏肽键。"],"check":{"kind":"short","id":"bc03_fig4_check","q":"尿素和盐酸胍主要破坏哪类作用力？","a":"与主链竞争氢键，破坏次级键，使构象解体。","e":"氢键竞争。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig4_exam","q":"SDS主要破坏？","o":["A. 疏水作用","B. 肽键","C. 二硫键","D. 磷酸二酯键"],"a":"A","e":"SDS破坏疏水相互作用，使蛋白变性。","src":"原书单图·选择"},"i":75,"imageExplain":"这张图主要在讲：原书变性示意图的单图裁切。看图时先找主体结构/坐标或箭头，再看标注；本页要抓住：尿素/盐酸胍竞争氢键。；SDS破坏疏水作用。。"},{"title":"原书单图：RNase复性（图3-57）","img":"assets/img/bc03book/fig-anfinsen.png","notes":"原书图3-57的单图裁切。看β-巯基乙醇还原二硫键、尿素变性，去除后氧化复性、活性恢复。","points":["β-巯基乙醇还原二硫键。","尿素破坏次级键。","去除变性剂后复性，说明序列决定结构。"],"check":{"kind":"short","id":"bc03_fig5_check","q":"Anfinsen实验中β-巯基乙醇和尿素各起什么作用？","a":"β-巯基乙醇还原二硫键；尿素破坏氢键/次级键。去除后可复性。","e":"还原+变性。","src":"原书单图·自测"},"exam":{"kind":"mcq","id":"bc03_fig5_exam","q":"Anfinsen实验说明？","o":["A. 序列决定结构","B. 变性不可逆","C. 肽键断裂","D. 二硫键不能重建"],"a":"A","e":"复性后活性恢复，说明一级序列决定天然构象。","src":"原书单图·选择"},"i":76,"imageExplain":"这张四格图在讲 Anfinsen 经典实验。第一格：天然 RNase 有活性和正确二硫键；第二格：加尿素/β-巯基乙醇，二硫键被还原、构象展开、活性丧失；第三格：去除变性剂，蛋白开始折叠；第四格：二硫键重新氧化，活性恢复。结论：一级序列决定天然三维结构。看图按 A→D 顺序看“变性→复性→活性恢复”。"},{"sec":"第3章 · 反应式速查","title":"第3章相关反应式速查","notes":"第3章反应式少：重点是二硫键氧化/还原、胶原交联；肽键形成/水解在bc02已学。","points":["二硫键氧化：2 Cys-SH ⇌ Cys-S-S-Cys + 2H⁺ + 2e⁻；还原反向。","DTT/β-巯基乙醇还原二硫键；过甲酸氧化断键。","胶原交联：赖氨酰氧化酶把Lys/Hyl的—NH₂氧化成醛基，再缩合成吡啶啉等。","肽键形成脱H₂O，水解加H₂O；变性不是化学反应式。"],"table":[["反应","条件/意义"],["2 Cys-SH ⇌ Cys-S-S-Cys + 2H⁺ + 2e⁻","氧化成键/还原断键；稳定三级/四级结构"],["Lys/Hyl—NH₂ → 醛基（赖氨酰氧化酶）","胶原交联第一步；维生素C参与羟化"],["醛基 + Lys/Hyl—NH₂ → 吡啶啉等","成熟交联，增加组织刚性"],["氨基酸 + 氨基酸 → 肽 + H₂O","肽键形成；水解为逆向"]],"tableTitle":"第3章相关反应式","check":{"kind":"short","id":"bc03_r1_check","q":"写出二硫键氧化成键的反应式。","a":"2 Cys-SH ⇌ Cys-S-S-Cys + 2H⁺ + 2e⁻；还原剂可使其逆向。","e":"氧化成键、还原断键。","src":"反应式·自测"},"exam":{"kind":"mcq","id":"bc03_r1_exam","q":"二硫键氧化成键时脱去？","o":["A. 2H⁺和2e⁻","B. H₂O","C. CO₂","D. NH₃"],"a":"A","e":"两个—SH氧化脱2H⁺和2e⁻形成S—S。","src":"反应式·选择"},"i":77},{"title":"难点精讲1：Ramachandran图到底在画什么","notes":"Ramachandran图以主链二面角φ（Cα–N）和ψ（Cα–C）为坐标；不是所有角度都允许，因为原子会碰撞。α螺旋落在φ≈−57°、ψ≈−47°附近，β折叠落在φ≈−120°、ψ≈+130°附近；Gly允许范围大，Pro受环限制。","points":["坐标是φ/ψ，不是键长。","允许区由空间位阻决定。","α/β有特征角度区。","Gly宽、Pro窄。"],"check":{"kind":"short","id":"bc03_h1","q":"Ramachandran图的横纵坐标？","a":"φ和ψ二面角。","e":"φ/ψ。","src":"难点精讲·自测"},"sec":"第03章 · 难点精讲","i":78},{"title":"难点精讲2：Bragg方程与X射线“相位问题”","notes":"Bragg方程nλ=2d sinθ把衍射角θ和晶面间距d连起来；但衍射只记录振幅，丢失相位，不能直接算出电子密度，这就是相位问题。常用多对同晶置换/分子替换解决。分辨率越高，能看到的细节越细；晶体堆积可能影响柔性区。","points":["nλ=2d sinθ。","θ→d，但相位丢失。","重原子/分子替换解相位。","分辨率决定细节。"],"check":{"kind":"short","id":"bc03_h2","q":"X射线晶体学的相位问题是什么？","a":"衍射丢失相位，需额外方法恢复电子密度。","e":"振幅有、相位丢。","src":"难点精讲·自测"},"sec":"第03章 · 难点精讲","i":79},{"title":"难点精讲3：CD、NMR、冷冻电镜怎么选","notes":"CD测溶液中二级结构比例：α螺旋在208/222 nm负峰，β折叠约218 nm，无规约198 nm；只给总体比例，不给原子模型。NMR给溶液中小蛋白原子级结构/动态；冷冻电镜适合大复合物/膜蛋白。X射线适合可结晶、高分辨率静态结构。","points":["CD：溶液二级结构比例。","NMR：小蛋白溶液结构/动态。","cryo-EM：大复合物/膜蛋白。","X-ray：晶体高分辨率。"],"check":{"kind":"short","id":"bc03_h3","q":"CD能给出原子级三维结构吗？","a":"不能，只给二级结构比例/构象变化。","e":"不能。","src":"难点精讲·自测"},"sec":"第03章 · 难点精讲","i":80},{"title":"难点精讲4：Anfinsen实验与折叠热力学","notes":"Anfinsen证明：变性RNase在适当条件下可自发改回天然构象，说明一级结构决定三维结构。天然态是自由能最低态，ΔG=ΔH−TΔS；疏水效应是主要驱动力之一。Levinthal佯谬说明不能随机搜索所有构象，实际走折叠路径/能量景观；体内常有分子伴侣协助。","points":["变性→复性可恢复活性。","一级结构决定三维结构。","天然态=自由能最低。","疏水效应+折叠路径/伴侣。"],"check":{"kind":"short","id":"bc03_h4","q":"Anfinsen实验说明什么？","a":"一级结构决定三维结构，折叠信息在序列中。","e":"序列决定结构。","src":"难点精讲·自测"},"sec":"第03章 · 难点精讲","i":81},{"title":"卡点闭环1-诊断：Ramachandran图","notes":"先做：α螺旋在Ramachandran图上的位置最接近哪一组φ/ψ？","points":["A. φ≈−57°，ψ≈−47°","B. φ≈−120°，ψ≈+130°","C. φ≈0°，ψ≈0°","D. φ≈+90°，ψ≈+90°"],"table":[["常见错答","错在哪"],["选B","那是β折叠区"],["选C","空间位阻不允许"],["选D","不是允许区"]],"tableTitle":"答案：A。α螺旋在φ≈−57°、ψ≈−47°附近。","sec":"第03章 · 卡点闭环","i":82},{"title":"卡点闭环1-例题：怎么读图","notes":"Ramachandran图横轴φ、纵轴ψ，每个点是一种主链构象；允许区由原子间空间位阻决定。α螺旋和β折叠各有特征区。","points":["横轴φ，纵轴ψ。","允许区=不碰撞的构象。","α螺旋：φ≈−57°，ψ≈−47°。","β折叠：φ≈−120°，ψ≈+130°。","Gly允许范围宽；Pro受环限制。"],"check":{"kind":"short","id":"bc03_c1_ex","q":"Ramachandran图的横纵坐标是什么？","a":"φ和ψ二面角。","e":"不是键长/键角。","src":"卡点闭环·例题"},"sec":"第03章 · 卡点闭环","i":83},{"title":"卡点闭环1-变式：α、β、Gly、Pro","notes":"先找特征区，再考虑残基限制。","table":[["结构/残基","φ/ψ特征","说明"],["α螺旋","−57/−47","右手螺旋"],["β折叠","−120/+130","片层"],["Gly","允许区大","无侧链，位阻小"],["Pro","允许区小","吡咯环限制"]],"tableTitle":"变式答案：先记α/β两区，再记Gly宽、Pro窄。","sec":"第03章 · 卡点闭环","i":84},{"title":"卡点闭环1-错因：把图当“地图”背","notes":"错因：①把φ/ψ当键长/键角；②以为禁区绝对不可能；③忽略Gly/Pro；④把α/β区域记反。","points":["φ/ψ是二面角，不是键长。","禁区=强空间位阻，极难稳定。","Gly宽、Pro窄。","α：−57/−47；β：−120/+130。","先判断二级结构，再定位。"],"sec":"第03章 · 卡点闭环","i":85},{"title":"卡点闭环2-诊断：Bragg方程","notes":"先做：Bragg方程nλ=2d sinθ中，θ最准确指什么？","points":["A. 任意入射角","B. 入射/衍射方向与晶面的夹角（Bragg角）","C. 检测器上的2θ","D. 晶胞边长"],"table":[["常见错答","错在哪"],["选A","θ不是任意角"],["选C","2θ是散射角，θ是半角"],["选D","d才是晶面间距"]],"tableTitle":"答案：B。θ是Bragg角；d是晶面间距。","sec":"第03章 · 卡点闭环","i":86},{"title":"卡点闭环2-例题：算θ","notes":"λ=1.54 Å，d=3.0 Å，n=1：sinθ=λ/(2d)=1.54/6.0=0.257，θ≈14.9°。若用2θ表示散射角，则2θ≈29.8°。","points":["写公式：nλ=2d sinθ。","代入λ、d、n。","求sinθ。","反算θ；区分θ与2θ。"],"check":{"kind":"short","id":"bc03_c2_ex","q":"λ=1.54Å，d=2.0Å，n=1，求θ。","a":"sinθ=1.54/4=0.385，θ≈22.6°。","e":"注意单位一致。","src":"卡点闭环·例题"},"sec":"第03章 · 卡点闭环","i":87},{"title":"卡点闭环2-变式：θ、d、分辨率","notes":"先算sinθ，再看n；θ越大，d越小，通常分辨率越高。","table":[["d(Å)","sinθ(n=1)","θ"],["3.0","0.257","14.9°"],["2.0","0.385","22.6°"],["1.5","0.513","30.9°"]],"tableTitle":"变式答案：d越小，θ越大；高分辨率看更小d。","sec":"第03章 · 卡点闭环","i":88},{"title":"卡点闭环2-错因：θ/2θ与相位问题","notes":"错因：①把θ当2θ；②以为有了振幅就能直接算电子密度；③忘了相位问题；④把晶面间距d和晶胞参数混为一谈。","points":["θ=Bragg角；2θ=散射角。","衍射记录振幅，相位丢失。","重原子/分子替换解相位。","d是晶面间距。","分辨率越高，细节越细。"],"sec":"第03章 · 卡点闭环","i":89},{"title":"卡点闭环3-诊断：CD能做什么","notes":"先做：圆二色光谱（CD）能不能直接给出原子级三维结构？","points":["A. 能，和X射线一样","B. 不能，只给二级结构比例/构象变化","C. 只能测分子量","D. 只能测pI"],"table":[["常见错答","错在哪"],["选A","CD分辨率远低于原子级"],["选C","分子量用质谱/电泳"],["选D","pI用IEF"]],"tableTitle":"答案：B。CD是溶液构象/二级结构比例的快速探针。","sec":"第03章 · 卡点闭环","i":90},{"title":"卡点闭环3-例题：三种方法怎么选","notes":"先问三件事：样品是否可结晶？分子多大？要静态结构还是动态/构象？X射线要晶体、分辨率高；NMR适合小蛋白溶液结构和动态；冷冻电镜适合大复合物/膜蛋白。","points":["X射线：晶体、高分辨率。","NMR：小蛋白、溶液、动态。","cryo-EM：大复合物/膜蛋白。","CD：二级结构比例，不给原子模型。"],"table":[["方法","样品","能得到","局限"],["X-ray","晶体","原子模型","需结晶/相位"],["NMR","溶液小蛋白","结构+动态","分子量上限"],["cryo-EM","大复合物","近原子模型","设备/数据处理"],["CD","溶液","二级结构比例","低分辨率"]],"tableTitle":"方法选择先看样品状态和目标。","sec":"第03章 · 卡点闭环","i":91},{"title":"卡点闭环3-变式：选方法","notes":"先排除不可行条件，再选信息量最高的方法。","table":[["场景","首选","理由"],["可结晶 soluble 蛋白","X射线","高分辨率"],["小蛋白溶液动态","NMR","溶液/动态"],["膜蛋白复合物","cryo-EM","无需晶体"],["快速判断α/β比例","CD","溶液、快速"]],"tableTitle":"变式答案：晶体→X-ray；溶液小→NMR；大复合物→cryo-EM；二级结构→CD。","sec":"第03章 · 卡点闭环","i":92},{"title":"卡点闭环3-错因：方法混用","notes":"错因：①以为CD能给原子模型；②以为NMR适合所有大复合物；③以为冷冻电镜不需要纯化/数据处理；④忽略X射线需要晶体。","points":["CD只给二级结构比例。","NMR适合小蛋白溶液。","cryo-EM适合大/膜复合物。","X-ray需要晶体和相位。","方法互补，不是替代。"],"sec":"第03章 · 卡点闭环","i":93},{"sec":"第3章 · 使用评估","title":"bc03 使用评估与学习建议","notes":"本页评估基于当前网页版：bc03 已按原书第3章重建，老师第5章原图+AI串讲+过程版+题库。","points":["覆盖：原书第3章九节，含四级结构、变性/折叠/预测、课后习题。","强项：41页notes重写+6页原书页+5页原书单图+6页AI图解+公式+7页习题精解。","短板：部分原书图仍需对照整页；下载版需重新生成。","适合：第3章自学/复习/考研基础题。","新增：第3章相关反应式速查（二硫键/胶原交联/肽键）。"],"table":[["维度","评价"],["内容覆盖","原书第3章九节基本覆盖"],["讲解/过程","41页notes+原书页/单图+AI图解+公式"],["题库","章测43题+7页习题精解+页级51题"],["视觉","原书页+单图+AI图解，图源已标注"],["综合评分","约 90 分"]],"tableTitle":"bc03 当前评估","i":94}]}],"mcq":[{"id":"bc03_exam_mcq1","modI":0,"q":"α螺旋中i位残基的—NH主要与哪个残基的—CO形成氢键？","o":["A. i+4","B. i+1","C. i−4","D. 侧链"],"a":"A","e":"α螺旋为主链i→i+4氢键。","kp":""},{"id":"bc03_exam_mcq2","modI":0,"q":"β折叠的链间氢键方向通常？","o":["A. 与链长轴接近垂直","B. 与链长轴平行","C. 与侧链平行","D. 无方向"],"a":"A","e":"β折叠链间氢键与链长轴接近垂直。","kp":""},{"id":"bc03_exam_mcq3","modI":0,"q":"胶原蛋白的特征重复序列是？","o":["A. Gly-X-Y","B. Gly-Ala","C. Lys-Arg","D. Phe-Trp"],"a":"A","e":"胶原蛋白为(Gly-X-Y)n，Gly占1/3。","kp":""},{"id":"bc03_exam_mcq4","modI":0,"q":"研究溶液中蛋白质二级结构最常用的快速方法是？","o":["A. CD","B. X射线衍射","C. 冷冻电镜","D. 超速离心"],"a":"A","e":"圆二色性可快速判断α螺旋/β折叠含量。","kp":""},{"id":"bc03_exam_mcq5","modI":0,"q":"X射线衍射解析蛋白质结构通常需要？","o":["A. 晶体","B. 溶液","C. 膜","D. 活细胞"],"a":"A","e":"X射线衍射需要蛋白质晶体。","kp":""},{"id":"bc03_exam_mcq6","modI":0,"q":"“βαβ”属于？","o":["A. 超二级结构","B. 四级结构","C. 膜蛋白","D. 核酸结构"],"a":"A","e":"βαβ是二级结构的组合，属于超二级结构/motif。","kp":""},{"id":"bc03_exam_mcq7","modI":0,"q":"细菌视紫红质的跨膜结构是？","o":["A. 7次跨膜α螺旋","B. β桶","C. 单层β折叠","D. 无跨膜段"],"a":"A","e":"细菌视紫红质为7次跨膜α螺旋。","kp":""},{"id":"bc03_exam_mcq8","modI":0,"q":"球状蛋白内部通常富集？","o":["A. 疏水残基","B. 带电残基","C. 糖链","D. 核酸"],"a":"A","e":"疏水核心是球状蛋白稳定因素。","kp":""}],"judge":[{"id":"bc03_exam_judge1","modI":0,"q":"肽键的C—N键可以完全自由旋转。","a":"错","e":"肽键有部分双键性质，六原子共平面，不能自由旋转。","kp":""},{"id":"bc03_exam_judge2","modI":0,"q":"疏水作用通常是球状蛋白折叠的主要驱动力。","a":"对","e":"疏水残基埋入内部，减少水化熵损失。","kp":""},{"id":"bc03_exam_judge3","modI":0,"q":"α螺旋的螺距约为0.54 nm。","a":"对","e":"α螺旋3.6残基/圈，螺距0.54 nm。","kp":""},{"id":"bc03_exam_judge4","modI":0,"q":"胶原蛋白的Gly-X-Y重复中Gly约占1/3。","a":"对","e":"胶原蛋白Gly占残基总数1/3。","kp":""},{"id":"bc03_exam_judge5","modI":0,"q":"CD可以测定蛋白质的高分辨率三维结构。","a":"错","e":"CD只能快速判断二级结构，不能给高分辨率三维结构。","kp":""}],"fill":[{"id":"bc03_exam_fill1","modI":0,"q":"α螺旋每圈约含______个氨基酸残基。","a":"3.6","e":"α螺旋3.6残基/圈，螺距0.54 nm。","kp":""},{"id":"bc03_exam_fill2","modI":0,"q":"α螺旋的螺距约为______ nm。","a":"0.54","e":"α螺旋螺距0.54 nm。","kp":""},{"id":"bc03_exam_fill3","modI":0,"q":"β折叠中相邻氨基酸的轴心距约为______ nm。","a":"0.35","e":"β折叠轴心距0.35 nm。","kp":""},{"id":"bc03_exam_fill4","modI":0,"q":"胶原蛋白的特征重复序列是______。","a":"Gly-X-Y","e":"胶原蛋白为(Gly-X-Y)n。","kp":""},{"id":"bc03_exam_fill5","modI":0,"q":"Bragg方程为______。","a":"2dsinθ=nλ","e":"X射线衍射的Bragg方程。","kp":""}],"short":[{"id":"bc03_short1","modI":0,"q":"稳定蛋白质三维结构的作用力有哪些？","a":"氢键、疏水作用、范德华力、离子键；疏水作用常是主要驱动力。","kps":"每点1分","src":"教材","e":"弱作用力集体稳定；疏水作用驱动折叠。"},{"id":"bc03_short2","modI":0,"q":"肽键为什么具有平面刚性？","a":"肽键C—N具有部分双键性质，六个原子共平面，C—N不能自由旋转；φ/ψ可旋转。","kps":"部分双键+共平面","src":"教材","e":"共振使C—N有双键性。"},{"id":"bc03_short3","modI":0,"q":"Ramachandran图说明什么？","a":"以φ/ψ为坐标，显示主链可允许/不允许的构象区；Gly、Pro特殊。","kps":"φ/ψ+允许区+特殊残基","src":"教材","e":"空间位阻限制主链折叠。"},{"id":"bc03_short4","modI":0,"q":"α螺旋的结构参数有哪些？","a":"3.6残基/圈，螺距0.54 nm，i→i+4主链氢键，右手螺旋。","kps":"3.6/0.54/i→i+4","src":"教材","e":"记参数。"},{"id":"bc03_short5","modI":0,"q":"平行与反平行β折叠有什么区别？","a":"平行β折叠链方向相同，反平行方向相反；两者链间氢键模式/重复距离不同。","kps":"方向+氢键","src":"教材","e":"反平行更常见于球状蛋白。"},{"id":"bc03_short6","modI":0,"q":"胶原蛋白的结构特点是什么？","a":"Gly-X-Y重复，三条左手螺旋形成右手三股超螺旋；羟脯氨酸/羟赖氨酸参与稳定和交联。","kps":"Gly-X-Y+三股螺旋","src":"教材","e":"胶原蛋白为结构蛋白。"},{"id":"bc03_short7","modI":0,"q":"什么是结构域？","a":"三级结构中相对独立、常具独立功能/活性位点的折叠区；可重组/演化。","kps":"独立折叠+功能","src":"教材","e":"domain vs motif。"},{"id":"bc03_short8","modI":0,"q":"膜内在蛋白的跨膜段通常是什么结构？","a":"多为跨膜α螺旋，少数为β桶；膜外周蛋白靠离子键/氢键附着表面。","kps":"α螺旋/β桶","src":"教材","e":"细菌视紫红质7次跨膜α螺旋；孔蛋白β桶。"},{"id":"bc03_short9","modI":0,"q":"φ=−80°、ψ=+120°的poly-Gly螺旋手性和每圈残基数？","a":"左手螺旋；约3.0个残基/圈。","kps":"手性+残基/圈","src":"教材课后题","e":"根据Ramachandran图判断。"},{"id":"bc03_short10","modI":0,"q":"肽(a) LKAENDEAARAMSEA 与(b) CRAGGFPWDQPGTSN，哪个更可能形成α螺旋？为什么？","a":"(a)更可能；含较多螺旋倾向残基；(b)含Pro/Gly等破坏螺旋的残基。","kps":"螺旋倾向+破坏残基","src":"教材课后题","e":"Pro中断螺旋。"},{"id":"bc03_short11","modI":0,"q":"毒素蛋白β-ME处理前后SDS条带变化，能说明什么？","a":"两条不同多肽链通过链间二硫键连接；还原后每条链约13k。","kps":"二硫键+两条链","src":"教材课后题","e":"SDS+还原+末端标记。"},{"id":"bc03_short12","modI":0,"q":"为什么蛋白质中氢键的净稳定贡献比真空中低？","a":"折叠蛋白中氢键供体/受体与水竞争，形成/断裂氢键能量相互抵消，净贡献降低。","kps":"水竞争","src":"教材课后题","e":"环境竞争。"},{"id":"bc03_short13","modI":0,"q":"四聚体B与单体A相比，亚基界面氨基酸组成可能有什么差别？","a":"B的亚基界面富集疏水残基，A表面更极性；疏水作用驱动四聚体缔合。","kps":"界面疏水","src":"教材课后题","e":"亚基缔合驱动力。"},{"id":"bc03_short14","modI":0,"q":"为什么埋藏在非极性内部的多肽片段更易形成α螺旋？","a":"水环境竞争氢键，非极性内部减少竞争，螺旋氢键更稳定。","kps":"水竞争+内部环境","src":"教材课后题","e":"环境对氢键的影响。"}],"calc":[{"id":"bc03_exam_calc1","modI":0,"q":"λ=0.154 nm，θ=10°，n=1，求晶面间距d。","a":"d=0.154/(2sin10°)≈0.444 nm。","e":"Bragg方程2d sinθ=nλ。","kp":""},{"id":"bc03_exam_calc2","modI":0,"q":"36个残基的α螺旋约多长？","a":"36/3.6=10圈；10×0.54 nm=5.4 nm。","e":"长度≈(n/3.6)×0.54 nm。","kp":""},{"id":"bc03_exam_calc3","modI":0,"q":"一个难结晶的膜蛋白大复合物，选择哪种结构测定方法？说明理由。","a":"冷冻电镜；适合大复合物/膜蛋白，可在近天然环境解析，避免长晶体。","e":"方法选择看样品状态和分辨率。","kp":""},{"id":"bc03_exam_calc4","modI":0,"q":"某纤维蛋白富含Gly-X-Y重复并形成三股螺旋，判断它是什么蛋白并说明依据。","a":"胶原蛋白；Gly-X-Y重复、Gly占1/3、三股螺旋、羟脯氨酸/羟赖氨酸交联。","e":"序列+结构双指纹。","kp":""},{"id":"bc03_exam_calc5","modI":0,"q":"78个残基的α螺旋轴长和完全伸展长度各是多少？","a":"轴长=78×0.15=11.7 nm；完全伸展=78×0.36=28.08 nm。","e":"分清每残基上升0.15 nm与伸展0.36 nm。","kp":""},{"id":"bc03_exam_calc6","modI":0,"q":"某蛋白Mr=240000，肽链长506 nm，α螺旋每残基0.15 nm、β折叠每残基0.35 nm，求α螺旋比例。","a":"残基数≈2182；0.15x+0.35(2182−x)=506；x≈1289；比例≈59%。","e":"先算残基数，再解方程。","kp":""}],"term":[{"id":"bc03_exam_term1","modI":0,"term":"疏水作用","def":"非极性基团避开水、聚集在内部，减少水化熵损失的作用；是球状蛋白折叠的主要驱动力。","kps":"非极性+避水+熵","kp":""},{"id":"bc03_exam_term2","modI":0,"term":"Ramachandran图","def":"以主链二面角φ/ψ为坐标，显示蛋白质主链可允许和不允许构象区的图。","kps":"φ/ψ+允许区","kp":""},{"id":"bc03_exam_term3","modI":0,"term":"结构域","def":"三级结构中相对独立、常具独立功能的折叠区，可重组和演化。","kps":"独立折叠+功能","kp":""},{"id":"bc03_exam_term4","modI":0,"term":"卷曲螺旋","def":"两条或多条α螺旋相互缠绕形成的超二级结构，α-角蛋白中常见。","kps":"α螺旋+缠绕","kp":""},{"id":"bc03_exam_term5","modI":0,"term":"β桶","def":"由β折叠片卷成筒状的结构，常见于孔蛋白和膜蛋白。","kps":"β折叠+筒状","kp":""}],"toc":[{"title":"一、蛋白质三维结构概述","pages":"PPT 1—7","start":0,"end":7,"items":[{"title":"弱作用力、肽键平面、Ramachandran图","start":0,"end":7}]},{"title":"二、测定蛋白质三维结构的方法","pages":"PPT 8—14","start":7,"end":14,"items":[{"title":"X射线、NMR、CD、冷冻电镜","start":7,"end":14}]},{"title":"三、蛋白质的二级结构","pages":"PPT 15—28","start":14,"end":28,"items":[{"title":"α螺旋、β折叠、转角、无规卷曲","start":14,"end":28}]},{"title":"四、纤维状蛋白质","pages":"PPT 29—45","start":28,"end":45,"items":[{"title":"α-角蛋白、丝心蛋白、胶原蛋白、弹性蛋白","start":28,"end":45}]},{"title":"五、超二级结构和结构域","pages":"AI 1页","start":45,"end":46,"items":[{"title":"motif与domain","start":45,"end":46}]},{"title":"六、球状蛋白质与三级结构","pages":"AI 1页","start":46,"end":47,"items":[{"title":"疏水核心、结构域、活性位点","start":46,"end":47}]},{"title":"七、膜蛋白的结构","pages":"AI 1页","start":47,"end":48,"items":[{"title":"跨膜α螺旋/β桶","start":47,"end":48}]},{"title":"八、四级结构和亚基缔合","pages":"AI 1页","start":48,"end":49,"items":[{"title":"亚基、对称性、别构","start":48,"end":49}]},{"title":"九、变性、折叠和结构预测","pages":"AI 2页","start":49,"end":51,"items":[{"title":"变性/复性、折叠、预测","start":49,"end":51}]},{"title":"AI图解：第5–9节","pages":"6页","start":51,"end":57,"items":[{"title":"结构域/球状/膜/四级/变性/折叠","start":51,"end":57}]},{"title":"公式精讲（5页）","pages":"5页","start":57,"end":62,"items":[{"title":"Bragg/α螺旋/β折叠/ΔG/残基数","start":57,"end":62}]},{"title":"过程版与实验设计","pages":"4页","start":62,"end":66,"items":[{"title":"Bragg、螺旋参数、纤维识别、方法选择","start":62,"end":66}]},{"title":"原书页扫描","pages":"6页","start":66,"end":72,"items":[{"title":"结构域/球状/膜/四级/变性/Anfinsen","start":66,"end":72}]},{"title":"原书单图卡片","pages":"5页","start":72,"end":77,"items":[{"title":"结构域/溶菌酶/血型糖蛋白/变性/RNase复性","start":72,"end":77}]},{"title":"第3章相关反应式","pages":"1页","start":77,"end":78,"items":[{"title":"二硫键/胶原交联/肽键","start":77,"end":78}]},{"title":"难点精讲（4页）","pages":"4页","start":78,"end":82,"items":[{"title":"学生最难理解的机制/公式/方法补充","start":78,"end":82}]},{"title":"卡点闭环（12页）","pages":"12页","start":82,"end":94,"items":[{"title":"诊断/例题/变式/错因四页一组","start":82,"end":94}]},{"title":"使用评估","pages":"1页","start":94,"end":95,"items":[{"title":"bc03评估与建议","start":94,"end":95}]}],"exercises":[{"id":"bc03_ex1","no":1,"type":"计算","q":"(1) 计算一个含有78个氨基酸的α-螺旋的轴长。(2) 此多肽的α-螺旋完全伸展时多长？","kp":"α螺旋几何参数；每残基上升0.15 nm，完全伸展0.36 nm。","analysis":"α螺旋每残基沿轴上升0.15 nm，所以78×0.15=11.7 nm；完全伸展时每残基0.36 nm，78×0.36=28.08 nm。","answer":"轴长=78×0.15=11.7 nm；完全伸展=78×0.36=28.08 nm。","slide":16,"slideTitle":"α螺旋的结构参数"},{"id":"bc03_ex2","no":2,"type":"计算","q":"某一蛋白质的多肽链除一些区段为α-螺旋外，其他区段均为β-折叠。该蛋白质相对分子质量为240000，多肽链外形长度为5.06×10⁻⁵ cm。试计算α-螺旋和β-折叠构象中氨基酸残基的百分数（β-折叠中每残基长度0.35 nm）。","kp":"残基数估算；α/β长度加权方程。","analysis":"残基数≈240000/110≈2182；长度506 nm。设α螺旋x个残基，则0.15x+0.35(2182−x)=506；解得x≈1289。α螺旋比例1289/2182≈59%，β折叠约41%。","answer":"残基数≈240000/110≈2182；0.15x+0.35(2182−x)=506，解得x≈1289；α螺旋≈59%，β折叠≈41%。","slide":22,"slideTitle":"β折叠片"},{"id":"bc03_ex3","no":3,"type":"简答","q":"虽然在真空中氢键键能约为20 kJ/mol，但在折叠的蛋白质中它对蛋白质稳定焓的贡献却要小得多（约5 kJ/mol）。试解释这种差别的原因。","kp":"氢键；水竞争；折叠热力学。","analysis":"真空中20 kJ/mol是孤立氢键的键能；折叠蛋白中形成蛋白内氢键时，原来与水形成氢键的供体/受体被占用，相当于先断开水-蛋白氢键再形成蛋白内氢键，两个过程能量大部分抵消，所以净贡献只有约5 kJ/mol。","answer":"水竞争氢键：形成蛋白内氢键时破坏蛋白-水氢键，两个过程能量大部分抵消，所以净贡献从20降到约5 kJ/mol。","slide":2,"slideTitle":"稳定三维结构的作用力"},{"id":"bc03_ex4","no":4,"type":"简答","q":"多聚甘氨酸能形成φ=−80°、ψ=+120°的螺旋。根据拉氏构象图，描述该螺旋的(1)手性；(2)每圈残基数。","kp":"Ramachandran图；φ/ψ；左手螺旋。","analysis":"φ=−80°、ψ=+120°落在拉氏图的左手螺旋允许区，因此是左手螺旋；该区域对应每圈约3.0个残基。","answer":"φ=−80°、ψ=+120°位于左手螺旋允许区；左手螺旋，约3.0残基/圈。","slide":5,"slideTitle":"Ramachandran图：可允许的φ/ψ"},{"id":"bc03_ex5","no":5,"type":"简答","q":"α-螺旋的稳定性不仅取决于肽链间氢键，还取决于侧链性质。试预测室温溶液中下列多聚氨基酸哪些形成α螺旋、哪些形成其他有规则结构、哪些不能形成有规则结构，并说明理由（多聚物列表见教材）。","kp":"螺旋倾向；pH与侧链电荷；Pro/Gly。","analysis":"先看pH决定侧链电荷：Glu/Lys在pH7带电，同种电荷排斥，不利α螺旋；Leu/Ala等螺旋倾向残基有利；Pro中断螺旋，Gly柔性大；把pH调到等电附近可减弱电荷排斥。","answer":"按“pH→侧链电荷、螺旋倾向、Pro/Gly”判断：Leu等倾向高；Glu/Lys在pH7带电不利；Pro不能形成α螺旋；调pH可改变结果。","slide":20,"slideTitle":"影响α螺旋形成的因素"},{"id":"bc03_ex6","no":6,"type":"简答","q":"多聚甘氨酸的右手或左手α螺旋中哪一个比较稳定？为什么？","kp":"Gly无侧链手性；对映体；能量相等。","analysis":"Gly没有侧链，α-碳上两个H，不具手性；多聚Gly的右手和左手α螺旋互为对映体，能量相等。","answer":"Gly无侧链手性，多聚Gly左右手螺旋为对映体，能量相当。","slide":21,"slideTitle":"其他类型的螺旋"},{"id":"bc03_ex7","no":7,"type":"计算","q":"一个含101残基的蛋白质有200个可旋转键，每个键Δφ有两个定位。(1)可能有多少种随机构象W？(2)计算1 mol该蛋白质折叠成天然构象的熵变。(3)若折叠成由100个氢键稳定的α螺旋，每个氢键焓贡献−5 kJ/mol，求ΔH折叠。(4)求25℃时ΔG折叠，判断折叠形式是否稳定。","kp":"构象熵；W=2^N；ΔG=ΔH−TΔS。","analysis":"W=2²⁰⁰=1.61×10⁶⁰；折叠使熵降低，ΔS≈−1.15 kJ/(K·mol)；ΔH=−5×100=−500 kJ/mol；ΔG=ΔH−TΔS=−500−298×(−1.15)≈−157 kJ/mol，ΔG<0，折叠稳定。","answer":"W=2²⁰⁰≈1.61×10⁶⁰；ΔS≈−1.15 kJ/(K·mol)，ΔH=−500 kJ/mol；ΔG=−500−298×(−1.15)≈−157 kJ/mol<0，折叠稳定。","slide":50,"slideTitle":"AI串讲9：折叠与结构预测"},{"id":"bc03_ex8","no":8,"type":"简答","q":"两个多肽链A和B有着相似的三级结构；正常情况下A以单体存在，B以四聚体(B4)存在。问A和B的氨基酸组成可能有什么差别。","kp":"亚基缔合；疏水界面；表面极性。","analysis":"单体A表面主要与水接触，亲水/极性残基多；四聚体B靠亚基界面把四个亚基“粘”在一起，界面需要埋藏疏水残基，靠疏水作用提供缔合驱动力。","answer":"B的亚基界面富集疏水残基，靠疏水作用缔合；A表面更亲水、更极性。","slide":48,"slideTitle":"AI串讲8：四级结构与亚基缔合"},{"id":"bc03_ex9","no":9,"type":"简答","q":"下面两个肽(a) LKAENDEAARAMSEA 和 (b) CRAGGFPWDQPGTSN，哪一个更可能采取α螺旋？为什么？","kp":"螺旋倾向残基；Pro/Gly破坏螺旋。","analysis":"α螺旋倾向高的残基有Ala、Leu、Glu、Gln、Met等；Pro、Gly常破坏螺旋。肽(a)含较多螺旋倾向残基，肽(b)含Pro/Gly，故(a)更可能成α螺旋。","answer":"(a) LKAENDEAARAMSEA 更可能形成α螺旋；它含较多螺旋倾向残基，而(b)含Pro/Gly破坏螺旋。","slide":20,"slideTitle":"影响α螺旋形成的因素"},{"id":"bc03_ex10","no":10,"type":"综合","q":"下面的序列是球状蛋白的一部分，利用表3-8数据和Chou-Fasman经验规则预测此区域二级结构：RRPVVLMAACLRPVVFITYGDGGTYYHWYH。","kp":"Chou-Fasman；Pα/Pβ/Pt；滑窗。","analysis":"查每个残基的Pα/Pβ/Pt，按滑窗打分；连续高Pα→α螺旋，高Pβ→β折叠，高Pt→β转角。本例结果：4–11 α螺旋，14–19 β折叠，20–23 β转角，24–30 β折叠。","answer":"α螺旋：4–11；β折叠：14–19、24–30；β转角：20–23。","slide":50,"slideTitle":"AI串讲9：折叠与结构预测"},{"id":"bc03_ex11","no":11,"type":"简答","q":"完全暴露在水环境中和完全埋藏在非极性内部的两种多肽片段，哪一种更容易形成α螺旋？为什么？","kp":"水竞争氢键；非极性内部；螺旋稳定性。","analysis":"水会与主链C=O/N—H竞争氢键，削弱α螺旋的i→i+4氢键；非极性内部减少水竞争，螺旋氢键更稳定，所以更易形成α螺旋。","answer":"埋在非极性内部的多肽片段更容易形成α螺旋；水环境会竞争氢键，削弱螺旋稳定性。","slide":19,"slideTitle":"α螺旋的稳定性"},{"id":"bc03_ex12","no":12,"type":"综合","q":"一种酶Mr为300000，在酸性环境中可解离成两个不同组分，其中一个Mr 100000，另一个50000；大的组分占总蛋白三分之二，有催化活性，小的无活性。用β-巯基乙醇处理时，大的失去催化能力，沉降速度减小，但沉降图案只呈现一个峰。关于该酶结构可作什么结论？","kp":"亚基数；二硫键；催化活性；沉降。","analysis":"总Mr 300k，酸解离为100k和50k，质量比2:1→2个100k大组分+2个50k小组分；大组分有活性，β-ME处理后失活且沉降减小，说明大组分内部有二硫键维持催化构象。","answer":"酶含4个亚基：2个100k催化组分+2个50k无活性组分；100k催化组分内部有二硫键，β-ME还原后解离/失活。","slide":48,"slideTitle":"AI串讲8：四级结构与亚基缔合"},{"id":"bc03_ex13","no":13,"type":"综合","q":"一种植物毒素蛋白直接用SDS凝胶电泳分析时，区带位于肌红蛋白(Mr 16900)和β-乳球蛋白(Mr 37100)之间；用β-巯基乙醇和碘乙酸处理后仍得到一条区带，但位置靠近细胞色素c(Mr 13370)。该毒素蛋白与FDNB反应并酸水解后释放DNP-Gly和DNP-Tyr。关于此蛋白结构能作什么结论？","kp":"SDS-PAGE；二硫键；β-ME还原；N端标记。","analysis":"SDS前后分子量改变，说明有二硫键交联；β-ME+碘乙酸还原/封闭后只剩一条≈13k带，说明两条不同链各约13k；FDNB给出DNP-Gly和DNP-Tyr两个N端，证明两条链不同。","answer":"毒素蛋白由两条不同多肽链通过链间二硫键连接，每条约13k；FDNB给出DNP-Gly和DNP-Tyr两个不同N端。","slide":2,"slideTitle":"稳定三维结构的作用力"},{"id":"bc03_ex14","no":14,"type":"综合","q":"一种蛋白质由相同亚基组成四聚体。(1)说出两种可能的对称性；稳定缔合是同种还是异种相互作用？(2)若四聚体如血红蛋白由两个相同单位（每单位含α和β链）组成，最高对称性是什么？","kp":"四级结构；对称性；C4/D2；Hb；C2。","analysis":"四聚体可由同种/异种缔合形成，常见C4或D2对称；Hb的αβ二聚体不对称，最高对称性C2。","answer":"(1) C4或D2；C4为异种缔合，D2为同种缔合（按教材）。(2) Hb最高对称性C2。","slide":48,"slideTitle":"AI串讲8：四级结构与亚基缔合"},{"id":"bc03_ex15","no":15,"type":"综合","q":"证明多阶段装配比单阶段更容易控制蛋白质质量：复合物含6个相同二聚体，每个由A(300 aa)和B(700 aa)组成；错误频率10⁻⁸；比较多阶段与一步合成的缺陷复合物频率。","kp":"装配质量控制；多阶段剔除缺陷；错误频率。","analysis":"一步合成6000 aa链错误概率高；多阶段装配每步可100%剔除缺陷，缺陷不会带入下一步，最终缺陷复合物频率更低。","answer":"多阶段装配缺陷复合物频率更低：每步可剔除缺陷，不会把错误带入下一步；一步合成6000 aa链错误会累积。","slide":48,"slideTitle":"AI串讲8：四级结构与亚基缔合"}]};